/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_histins_to_wrongnote_once` AFTER INSERT ON `history` FOR EACH ROW BEGIN
  IF NEW.is_correct = 0
     AND NEW.quiz_id IS NOT NULL THEN
    INSERT IGNORE INTO ai_go.wrong_note (user_id, wrong_quiz_id)
    VALUES (NEW.user_id, NEW.quiz_id);
  END IF;
