DROP TABLE IF EXISTS `options`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `options` (
  `option_id` varchar(36) NOT NULL COMMENT 'PK. 선지 고유번호',
  `quiz_id` varchar(36) NOT NULL COMMENT 'FK → quiz.quiz_id',
  `label` tinyint unsigned NOT NULL COMMENT '선지 번호 (1,2,3,4)',
  `option_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '선택지 내용',
  `explanation_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '해설 내용',
  `is_answer` tinyint(1) NOT NULL DEFAULT '0' COMMENT '해당 선지가 정답인지 아닌지',
  PRIMARY KEY (`option_id`),
  UNIQUE KEY `uq_options_quiz_label` (`quiz_id`,`label`),
  KEY `quiz_id_idx` (`quiz_id`),
  CONSTRAINT `fk_options_quiz` FOREIGN KEY (`quiz_id`) REFERENCES `quiz` (`quiz_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `chk_options_label` CHECK ((`label` between 1 and 4))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='퀴즈 :  선지 - 해설';
