LOCK TABLES `options` WRITE;
/*!40000 ALTER TABLE `options` DISABLE KEYS */;
INSERT INTO `options` VALUES ('01c7845c-7c48-11f0-a0df-bcfce7e0bced','110353_middle_3',1,'어린이 보호구역','도로교통법 시행규칙 [별표 6] “영 제10조의3제2항에 따라 설치하는 소방시설 주변 정차·주차금지표시 및 보호구역(어린이ᆞ노인ᆞ장애인) 또는 주거지역 안에 설치하는 속도제한표시의 테두리선: 빨간색 또는 흰색” 에 따르면 어린이 보호구역에서 속도 억제 및 시인성 확보 목적으로 적색 포장을 합니다.',0),('0201f341-7c44-11f0-a0df-bcfce7e0bced','zigzag_basic_0',3,'교통 혼잡을 줄이기 위한 장치다.','서행 안전표지는 교통안전시설(노면표시) 설치·관리 업무편람”에 따르면 교통량 조절 목적은 아니며, 보행자 안전 중심입니다.',0),('05d4db93-7c44-11f0-a0df-bcfce7e0bced','zigzag_basic_0',4,'오토바이나 자전거만 해당되는 표시다.','도로교통법 제31조1항 : “모든 차 또는 노면전차의 운전자는 다음 각 호의 어느 하나에 해당하는 곳에서는 서행하여야 한다”에 따라 모든 차에 적용되는 표시입니다.',0),('06067ec4-7c40-11f0-a0df-bcfce7e0bced','87769_middle_2',2,'경적을 울려 상대방에게 양보를 요구한다.','경적은 제49조 제1항에 따라 “위험 방지를 위한 경우”에만 사용할 수 있으며 양보 강요 수단이 아닙니다.',0),('062906b5-7c48-11f0-a0df-bcfce7e0bced','110353_middle_3',2,'고속도로 진·출입로','도로교통법 시행규칙 [별표 6]에 의해 고속도로 진·출입로의 경우 주행 안전을 위해 노란선, 흰색 차선만 있으며 적색 포장은 사용되지 않습니다.',1),('06e2ec9f-7c42-11f0-a0df-bcfce7e0bced','191130_hard_0',1,'차량 신호가 녹색이므로 보행자보다 차량이 우선한다.','도로교통법 제27조 제1항은 신호와 관계없이 보행자가 횡단보도를 통행하고 있으면 모든 차는 정지해야 한다고 명시합니다. 녹색 신호라도 차량이 우선이 아닙니다.',0),('0aa3416d-7c48-11f0-a0df-bcfce7e0bced','110353_middle_3',3,'사고다발지역','국토교통부에 따르면 사고다발지역에서 위험 경고 목적의 적색 포장 사용 가능합니다.',0),('0ef92221-7c48-11f0-a0df-bcfce7e0bced','110353_middle_3',4,'소방시설 주 · 정차구역','도로교통법 시행규칙 [별표 6] “영 제10조의3제2항에 따라 설치하는 소방시설 주변 정차·주차금지표시 및 보호구역(어린이ᆞ노인ᆞ장애인) 또는 주거지역 안에 설치하는 속도제한표시의 테두리선: 빨간색 또는 흰색” 에 따르면 소방시설 주·정차구역에서 불법 주정차 방지를 위해 적색 포장을 사용합니다.',0),('0fa7e687-7c3e-11f0-a0df-bcfce7e0bced','87769_middle_0',4,'차량 크기가 작은 차량이 상대적으로 큰 차량에게 양보해야 한다.','도로교통법은 차량의 크기만을 기준으로 양보 의무를 규정하지 않습니다.\r\n제20조는 단순히 교행 곤란 시 일방이 양보하도록 규정할 뿐이며, “무조건 소형차 양보” 조항은 없습니다.',0),('11e9a54e-8240-11f0-afd0-d843ae853d20','87785_middle_1',1,'모든 차는 지정된 차로의 오른쪽 차로로 통행할 수 있다.','도로교통법 제13조(차마의 통행) 3항 “차마의 운전자는 도로(보도와 차도가 구분된 도로에서는 차도를 말한다)의 중앙(중앙선이 설치되어 있는 경우에는 그 중앙선을 말한다. 이하 같다) 우측 부분을 통행하여야 한다.”에 따르면 모든 차량은 차로의 오른쪽으로 통행 가능합니다.',0),('14cc5ad4-7c45-11f0-a0df-bcfce7e0bced','110353_middle_0',1,'공사 구역 접근 시, 차단된 2차로를 피하려고 1차로로 차선 변경','도로교통법 제 19조(안전거리 확보 등) “③ 모든 차의 운전자는 차의 진로를 변경하려는 경우에 그 변경하려는 방향으로 오고 있는 다른 차의 정상적인 통행에 장애를 줄 우려가 있을 때에는 진로를 변경하여서는 아니 된다.” 에 따라 위반이 아닙니다. 차선 변경 자체는 가능하며, 안전거리와 주변 차량 상황을 고려해 진행했다면 불법이 아닙니다. ',0),('15141413-8240-11f0-afd0-d843ae853d20','87785_middle_1',2,'차량이 앞선 차량을 앞지르기를 할 때에는 오른쪽 차로를 이용해 앞지르기를 해아 한다.','제21조 제1항(도로교통법)에 따르면 “다른 차를 앞지르려면 앞차의 좌측으로 통행하여야 한다.” 도로교통법 시행규칙 별표9에 따르면 앞지르기를 할 때에는 통행 기준에 지정된 차로의 바로 옆 왼쪽 차로로 통행할 수 있기 때문에 2번이 정답입니다.',1),('17227cc2-821f-11f0-afd0-d843ae853d20','98453_basic_1',1,'회전교차로에 먼저 진입해 회전하고 있는 차량이 통행 우선권을 가진다.','도로교통법 제25조의2(회전교차로 통행방법) \r\n”② 모든 차의 운전자는 회전교차로에 진입하려는 경우에는 서행하거나 일시정지하여야 하며, 이미 진행하고 있는 다른 차가 있는 때에는 그 차에 진로를 양보하여야 한다.” \r\n제2항에 따라 회전교차로에서는 회전차량이 통행 우선권을 가집니다.',1),('175dde83-8240-11f0-afd0-d843ae853d20','87785_middle_1',3,'편도 4차로 일반도로에서 승용자동차와 경형·소형·중형의 승합자동차의 주행차로는 모든 차로이며, 주로 왼쪽 차로를 이용한다.','도로교통법 시행규칙 [별표 9]에 따르면 승용차와 경중소형 승합차는 편도 4차로 일반도로에서 모든 차로를 통행할 수 있고 주로 왼쪽 차로를 이용하기 때문에 해당 선지는 오답입니다.',0),('17a5c1af-821a-11f0-afd0-d843ae853d20','154060_basic_1',1,'교차로','도로교통법 제22조(앞지르기 금지의 시기 및 장소) 3항 “모든 차의 운전자는 다음 각 호의 어느 하나에 해당하는 곳에서는 다른 차를 앞지르지 못한다. - 교차로, 터널 안, 다리 위, 도로의 구부러진 곳, 비탈길의 고갯마루 부근 또는 가파른 비탈길의 내리막 등 시ㆍ도경찰청장이 도로에서의 위험을 방지하고 교통의 안전과 원활한 소통을 확보하기 위하여 필요하다고 인정하는 곳으로서 안전표지로 지정한 곳” 에 따라 교차로 내에서는 앞지르기가 금지되어 있습니다.',0),('184f9e8e-8240-11f0-afd0-d843ae853d20','87785_middle_1',4,'편도 2차로 고속도로에서 해당 도로의 2차로에는 모든 자동차가 통행할 수 있다.','도로교통법 시행규칙 [별표 9] “고속도로 편도2차로 - 2차로 : 모든 자동차”에 따라 고속도로 편도 2차로의 2차로에서는 모든 자동차가 통행할 수 있습니다.',0),('19aab253-7c45-11f0-a0df-bcfce7e0bced','110353_middle_0',2,'공사 구역을 통과하며, 공사구간과 약 1m 간격으로 주행','공사구간 1m 간격 주행은 법적으로 위반이 아닙니다. 작업자가 울타리나 안전구역 안에 있다면 직접적인 접촉 위험이 없으므로 명백한 위반은 아닙니다. 단, 안전운전 의무(제48조)는 계속 적용됩니다.',0),('1a281f68-84b4-11f0-bb06-d843ae853d20','131062_hard_2',1,'차량 신호등 적색의 등화일 때, 정지선·횡단보도·교차로 직전에서 일단 정지한 후, 진행하는 다른 차마의 교통을 방해하지 않는 범위에서 우회전 가능하다. 단, 우회전 삼색등이 적색이면 우회전할 수 없다.','도로교통법 시행규칙 [별표 2] 차량 신호등 원형등화 적색의 등화 : \r\n1. 차마는 정지선, 횡단보도 및 교차로의 직전에서 정지해야 한다.\r\n2. 차마는 우회전하려는 경우 정지선, 횡단보도 및 교차로의 직전에서 정지한 후 신호에 따라 진행하는 다른 차마의 교통을방해하지 않고 우회전할 수 있다.\r\n3. 제2호에도 불구하고 차마는 우회전 삼색등이 적색의 등화인경우 우회전할 수 없다.\r\n\r\n표의 ‘적색의 등화’ 설명대로, 일시정지 후 타 교통을 방해하지 않으면 우회전 가능하되, 우회전 전용 3색등이 적색이면 우회전 금지입니다.',1),('1a9937bf-7c43-11f0-a0df-bcfce7e0bced','191130_hard_2',1,'차량 신호가 녹색이면 우선 통과한다.','도로교통법 제27조는 차량 신호와 무관하게 보행자 우선 원칙을 규정합니다.',0),('1b68035c-821f-11f0-afd0-d843ae853d20','98453_basic_1',2,'회전교차로에 진입하고자 하는 경우 원활한 교통을 위해 신속하게 진입하도록 한다.','- 도로교통법 제25조의2(회전교차로 통행방법)\r\n    \r\n    ② 모든 차의 운전자는 회전교차로에 진입하려는 경우에는 서행하거나 일시정지하여야 하며, 이미 진행하고 있는 다른 차가 있는 때에는 그 차에 진로를 양보하여야 한다.\r\n    \r\n    제2항에 따라 회전교차로에 진입하려는 차는 ‘서행하거나 일시정지’ 해야 합니다. 회전 중인 차가 있는지 확인하고 안전하게 합류하기 위함이므로, 신속히 진입하는 것은 매우 위험한 행동입니다.',0),('1bda31d6-821a-11f0-afd0-d843ae853d20','154060_basic_1',2,'중앙선(노란색 점선)','도로교통법 제22조(앞지르기 금지의 시기 및 장소) 3항에 따라 앞지르기가 금지된 시기 및 장소에 중앙선이 명시되어 있지 않기 때문에 앞지르기가 가능합니다.',1),('1c3c58c4-84b4-11f0-bb06-d843ae853d20','131062_hard_2',2,'적색 화살표 등화가 켜져 있어도 해당 방향으로 서행하며 통과할 수 있다.','도로교통법 시행규칙 [별표 2] 차량 신호등 화살표 등화 적색화살표의 등화 : \r\n화살표시 방향으로 진행하려는 차마는 정지선, 횡단보도 및 교차로의 직전에서 정지하여야 한다.\r\n\r\n적색 화살표 등화는 해당 방향 진행 금지이며, 정지선 등에서 정지해야 합니다. 서행 통과해선 안됩니다.',0),('1d9e40ff-8227-11f0-afd0-d843ae853d20','192029_hard_3',1,'회전교차로 진입 전 깜빡이를 켜고 좌회전하려는 차량','도로교통법 제25조의2(회전교차로 통행방법)에 따르면 회전차량의 통행이 우선이며, 회전교차로 설계지침(2014.12) 1.3.1 회전교차로 정의에 따르면 회전차량은 회전차로를 주행하는 차량이고, 진입차량은 회전교차로 진입 전 좌회전, 직진, 우회전하려는 차량을 말합니다. 해당 선지는 진입차량을 뜻하므로 통행 우선권이 보장된 회전차량이 아닙니다.',0),('1dacd26c-849d-11f0-bb06-d843ae853d20','110369_middle_1',1,'터널 안은 위험한 장소이기 때문에 하얀색 실선으로 차로변경을 금지하는 경우가 많다.','**도로교통법 시행규칙 [별표 6]** “차의 진로변경을 금지하는 도로구간에 백색실선을 설치” 에 따르면 차로변경 금지선은 실선으로 표시합니다. 따라서 하얀색 실선으로 표시된 곳에서는 차로변경이 제한됩니다. \r\n\r\n**도로교통법 제22조(앞지르기 금지의 시기 및 장소) 제3항** “모든 차의 운전자는 다음 각 호의 어느 하나에 해당하는 곳에서는 다른 차를 앞지르지 못한다. 1. 교차로 2. 터널 안 3. 다리 위 (중략)”에 따르면 터널 안에서는 다른 차량의 앞지르기를 금하고 있는데, 앞지르기를 하려면 차로변경이 필수이기 때문에 앞지르기를 금한다는 것은 차로변경을 금한다는 것과 마찬가지입니다.',1),('1dce4893-7c45-11f0-a0df-bcfce7e0bced','110353_middle_0',3,'횡단보도에 진입할 때, 보행자가 없음을 확인하고 그대로 주행','보행자가 없고 횡단보도 신호가 적색이라면 차량이 정지할 의무는 없습니다. 단, 횡단보도 진입 시 전방 주시와 서행 의무는 항상 적용됩니다. 따라서 위반이 아닙니다.',0),('1e14d244-84b4-11f0-bb06-d843ae853d20','131062_hard_2',3,'녹색 화살표 등화는 모든 방향으로 진행할 수 있음을 뜻한다.','도로교통법 시행규칙 [별표 2] 차량 신호등 화살표 등화 녹색화살표의 등화 :\r\n차마는 화살표시 방향으로 진행할 수 있다.\r\n\r\n녹색 화살표 등화는 화살표 방향으로만 진행을 허용한다는 뜻입니다. 모든 방향 허용이 아닙니다.',0),('1f60cb72-84b4-11f0-bb06-d843ae853d20','131062_hard_2',4,'자전거 횡단 신호등은 노면전차가 직·좌·우회전할 예정임을 뜻한다.','도로교통법 시행규칙 [별표 2] 자전거 신호등 자전거 횡단 신호등 :\r\n- 녹색의 등화 : 자전거 등은 자전거횡단도를 횡단할 수 있다.\r\n- 녹색 등화의 점멸 : 자전거등은 횡단을 시작해서는 안 되고, 횡단하고 있는 자전거등은 신속하게 횡단을 종료하거나 그 횡단을 중지하고 진행하던 차도 또는 자전거도로로 되돌아와야 한다. \r\n- 적색의 등화 : 자전거등은 자전거횡단도를 횡단해서는 안 된다.\r\n\r\n자전거 횡단 신호등은 자전거 횡단 허용과 관련된 신호로, 노면전차(트램) 진행 예고를 뜻하지 않습니다.',0),('1f71e1ed-8227-11f0-afd0-d843ae853d20','192029_hard_3',2,'회전교차로 진입 전 깜빡이를 켜고 우회전하려는 차량','도로교통법 제25조의2(회전교차로 통행방법)에 따르면 회전차량의 통행이 우선이며, 회전교차로 설계지침(2014.12) 1.3.1 회전교차로 정의에 따르면 회전차량은 회전차로를 주행하는 차량이고, 진입차량은 회전교차로 진입 전 좌회전, 직진, 우회전하려는 차량을 말합니다. 해당 선지는 진입차량을 뜻하므로 통행 우선권이 보장된 회전차량이 아닙니다.',0),('1fd8dfca-821a-11f0-afd0-d843ae853d20','154060_basic_1',3,'터널 안(하얀색 점선 차로)','도로교통법 제22조(앞지르기 금지의 시기 및 장소) 3항 “모든 차의 운전자는 다음 각 호의 어느 하나에 해당하는 곳에서는 다른 차를 앞지르지 못한다. - 교차로, 터널 안, 다리 위, 도로의 구부러진 곳, 비탈길의 고갯마루 부근 또는 가파른 비탈길의 내리막 등 시ㆍ도경찰청장이 도로에서의 위험을 방지하고 교통의 안전과 원활한 소통을 확보하기 위하여 필요하다고 인정하는 곳으로서 안전표지로 지정한 곳” 에 따라 터널 안에서는 앞지르기가 금지되어 있습니다.',0),('2023cc6b-849d-11f0-bb06-d843ae853d20','110369_middle_1',2,'차로변경을 금지하고자 하는 장소는 하얀색 점선으로 표시되어 있다.','도로교통법 시행규칙 [별표 6] “차의 진로변경을 금지하는 도로구간에 백색실선을 설치”에 따라 하얀색 점선이 아니라 하얀색 실선이 맞습니다.',0),('21c028cf-821f-11f0-afd0-d843ae853d20','98453_basic_1',3,'회전교차로는 시계방향으로 주행한다.','- 도로교통법 제25조의2(회전교차로 통행방법)\r\n“① 모든 차의 운전자는 회전교차로에서는 반시계방향으로 통행하여야 한다.” \r\n제1항에 따라 회전교차로에서는 반드시 반시계방향으로 주행해야 합니다.',0),('21cf3d9f-8227-11f0-afd0-d843ae853d20','192029_hard_3',3,'회전교차로 내 회전차로에서 주행 중인 차량','도로교통법 제25조의2(회전교차로 통행방법)에 따르면 회전차량의 통행이 우선이며, 회전교차로 설계지침(2014.12) 1.3.1 회전교차로 정의에 따르면 회전차량은 회전차로를 주행하는 차량이고, 진입차량은 회전교차로 진입 전 좌회전, 직진, 우회전하려는 차량을 말합니다. 해당 선지는 회전차량을 뜻하므로 통행 우선권이 보장됩니다.',1),('22048c64-7c43-11f0-a0df-bcfce7e0bced','191130_hard_2',2,'보행자가 천천히 걷는 경우 경적을 울려 빨리 가라고 한다.','경적 사용은 도로교통법 제49조에 따라 제한됩니다.',0),('22586ba8-821a-11f0-afd0-d843ae853d20','154060_basic_1',4,'다리 위(하얀색 점선 차로)','도로교통법 제22조(앞지르기 금지의 시기 및 장소) 3항 “모든 차의 운전자는 다음 각 호의 어느 하나에 해당하는 곳에서는 다른 차를 앞지르지 못한다. - 교차로, 터널 안, 다리 위, 도로의 구부러진 곳, 비탈길의 고갯마루 부근 또는 가파른 비탈길의 내리막 등 시ㆍ도경찰청장이 도로에서의 위험을 방지하고 교통의 안전과 원활한 소통을 확보하기 위하여 필요하다고 인정하는 곳으로서 안전표지로 지정한 곳” 에 따라 다리 위에서는 앞지르기가 금지되어 있습니다.',0),('229d67f3-849d-11f0-bb06-d843ae853d20','110369_middle_1',3,'차로변경이 금지되어 있는 장소에서는 도로 공사 등으로 통행이 불가능한 경우라도 차로변경을 하지 않고 주행해야 한다.','도로교통법 제14조(차로의 설치 등) 제5항 “차마의 운전자는 안전표지가 설치되어 특별히 진로 변경이 금지된 곳에서는 차마의 진로를 변경하여서는 아니 된다. 다만, 도로의 파손이나 도로공사 등으로 인하여 장애물이 있는 경우에는 그러하지 아니하다.”에 따르면 도로공사 등으로 장애물이 있으면 진로변경이 가능합니다.',0),('22c21f9b-8227-11f0-afd0-d843ae853d20','192029_hard_3',4,'회전교차로 진입 전 좌회전 및 우회전하려는 차량','도로교통법 제25조의2(회전교차로 통행방법)에 따르면 회전차량의 통행이 우선이며, 회전교차로 설계지침(2014.12) 1.3.1 회전교차로 정의에 따르면 회전차량은 회전차로를 주행하는 차량이고, 진입차량은 회전교차로 진입 전 좌회전, 직진, 우회전하려는 차량을 말합니다. 해당 선지는 진입차량을 뜻하므로 통행 우선권이 보장된 회전차량이 아닙니다.',0),('23cdd5c9-849d-11f0-bb06-d843ae853d20','110369_middle_1',4,'차로변경 금지장소에서 주변 교통상황을 살피면서 서행한다면 차로변경이 일시적으로 가능하다.','도로교통법 제14조(차로의 설치 등) 제5항 “차마의 운전자는 안전표지가 설치되어 특별히 진로 변경이 금지된 곳에서는 차마의 진로를 변경하여서는 아니 된다.”에 따라 차로변경 금지장소에서는 안전하게 차로를 변경하여도 법규 위반에 해당합니다.',0),('24a72bfe-7c45-11f0-a0df-bcfce7e0bced','110353_middle_0',4,'전방 직진 신호가 녹색이므로, 시속 50키로로 교차로를 통과','도로교통법 제12조(어린이 보호구역의 지정ㆍ해제 및 관리) “① 시장등은 교통사고의 위험으로부터 어린이를 보호하기 위하여 필요하다고 인정하는 경우에는 다음 각 호의 어느 하나에 해당하는 시설이나 장소의 주변도로 가운데 일정 구간을 어린이 보호구역으로 지정하여 자동차등과 노면전차의 통행속도를 시속 30킬로미터 이내로 제한할 수 있다.” 에 따르면 어린이 보호구역에서는 반드시 시속 30km/h 이내로 통행해야 합니다. 따라서 직진 신호가 녹색이더라도 50km/h로 교차로를 통과하는 것은 명백한 제한속도 위반입니다.',1),('24b51b86-822a-11f0-afd0-d843ae853d20','131062_hard_0',1,'교차로의 신호가 적색 점멸 신호(깜빡이는 빨간불)이므로 반드시 정지한 후, 신호가 녹색으로 바뀐 후에 직진한다.','도로교통법 시행규칙 별표2 – 적색 등화의 점멸 : “차마는 정지선이나 횡단보도가 있을 때에는 그 직전이나 교차로의 직전에 일시정지한 후 다른 교통에 주의하면서 진행할 수 있다.”\r\nA번은 적색 점멸 신호에서 반드시 정지하고, 신호가 녹색이 될 때까지 대기해야 한다고 설명하지만, 도로교통법 시행규칙에 따르면 적색 등화의 점멸 상황에서는 일시정지 후 주변을 살피면서 주행 가능하다고 명시되어 있으므로 오답입니다.',0),('24e1ea9f-84af-11f0-bb06-d843ae853d20','busstop_hard_2',1,'다른 차가 끼어들어 사고가 발생할 위험을 방지하기 위해서 경음기를 지속해서 사용하며 주행한다.','도로교통법 제49조(모든 운전자의 준수사항 등) “8. 운전자는 정당한 사유 없이 다음 각 목의 어느 하나에 해당하는 행위를 하여 다른 사람에게 피해를 주는 소음을 발생시키지 아니할 것 - 다. 반복적이거나 연속적으로 경음기를 울리는 행위”에 따라 지속적으로 경음기를 사용하는 것은 금지되어 있습니다.',0),('24e9cc49-821f-11f0-afd0-d843ae853d20','98453_basic_1',4,'회전교차로 진입 시 비상점멸등(차 뒷편의 빨간등)을  켜고 진입을 알린다.','도로교통법 시행령 [별표 2]에 따르면, 회전교차로 진입 시에는 좌측 방향지시등을, 진출(나갈 때)에는 우측 방향지시등을 켜야 합니다. 비상점멸등은 긴급상황을 알리는 등화이므로 일반적인 진입 신호로 사용하는 것은 옳지 않습니다.',0),('26fdce48-822a-11f0-afd0-d843ae853d20','131062_hard_0',2,'교차로의 신호가 적색 점멸 신호(깜빡이는 빨간불)이므로 일단 일시 정지한 후, 주변을 살핀 후 직진한다.','도로교통법 시행규칙 별표2 – 적색 등화의 점멸 : “차마는 정지선이나 횡단보도가 있을 때에는 그 직전이나 교차로의 직전에 일시정지한 후 다른 교통에 주의하면서 진행할 수 있다.”\r\nB번은 도로교통법 시행규칙 별표2의 내용인 적색 등화의 점멸 - “차마는 정지선이나 횡단보도가 있을 때에는 그 직전이나 교차로의 직전에 일시정지한 후 다른 교통에 주의하면서 진행할 수 있다.” 에 부합하기 때문에 정답입니다.',1),('272d250a-84af-11f0-bb06-d843ae853d20','busstop_hard_2',2,'오른쪽의 인도를 걷던 보행자가 무단 횡단할 수 있으므로 주의하며 주행한다.','도로교통법 제27조에 따라 차량 운전자는 보행자 보호의무가 있고, 중앙 버스전용차로 구간에서는 버스정류장이 도로 중앙에 위치해있고, 횡단보도 길이가 길지 않아 보행자가 무단 횡단할 가능성이 높기 때문에 항상 주의해서 운전해야 합니다.',1),('27482cb2-7c43-11f0-a0df-bcfce7e0bced','191130_hard_2',3,'보행자가 횡단 중이면 차량은 반드시 정지해야 한다.','도로교통법 제27조 제1항에 따라 횡단보도 보행자 통행 중이면 차량은 일시정지해야 합니다.',1),('298241ce-822a-11f0-afd0-d843ae853d20','131062_hard_0',3,'교차로의 신호가 적색 점멸 신호(깜빡이는 빨간불)이므로 다른 차량을 방해하지 않도록 정지하지 말고 천천히 직진한다.','도로교통법 시행규칙 별표2 – 적색 등화의 점멸 : “차마는 정지선이나 횡단보도가 있을 때에는 그 직전이나 교차로의 직전에 일시정지한 후 다른 교통에 주의하면서 진행할 수 있다.”\r\n도로교통법 시행규칙 별표2에 따르면 적색 등화의 점멸 시 반드시 일시정지한 후에 차량을 진행해야 하므로 C번은 오답입니다.',0),('2a44272c-84af-11f0-bb06-d843ae853d20','busstop_hard_2',3,'버스 정류장에 있던 보행자가 도로를 향해 나올 수 있으므로 서행한다.','도로교통법 제27조에 따라 차량 운전자는 보행자 보호의무가 있고, 중앙 버스전용차로 구간에서는 버스정류장이 도로 중앙에 위치해있고, 횡단보도 길이가 길지 않아 보행자가 무단 횡단할 가능성이 높기 때문에 항상 주의해서 운전해야 합니다.',1),('2a85b5f1-822a-11f0-afd0-d843ae853d20','131062_hard_0',4,'적색 점멸 신호(깜빡이는 빨간불)는 주의하라는 의미이므로 주변 교통 상황만 완벽하게 파악했다면 기존 속도로 교차로를 지나간다.','도로교통법 시행규칙 별표2 – 적색 등화의 점멸 : “차마는 정지선이나 횡단보도가 있을 때에는 그 직전이나 교차로의 직전에 일시정지한 후 다른 교통에 주의하면서 진행할 수 있다.”\r\n도로교통법 시행규칙 별표2에 따르면 적색 등화의 점멸 시 반드시 일시정지한 후에 차량을 진행해야 함을 명시하고 있는데, D번은 일시정지의 내용이 빠져있으므로 오답입니다.',0),('2bd6cc9e-84af-11f0-bb06-d843ae853d20','busstop_hard_2',4,'전방 신호가 빨간색으로 변경될 수 있으므로 교통 상황에 방해되지 않도록 신속하게 통과한다.','도로교통법 제48조(안전운전 및 친환경 경제운전의 의무) “도로의 교통상황과 차 또는 노면전차의 구조 및 성능에 따라 다른 사람에게 위험과 장해를 주는 속도나 방법으로 운전하여서는 아니 된다.”에 따라 무리하게 빠른 속도로 주행하는 것을 권장하지 않으며, 중앙 버스전용차로 구간은 보행자의 출현 위험이 큰 구역이기 때문에 서두르는 대신 안전을 우선시해야 합니다.',0),('2d1aa86b-7c43-11f0-a0df-bcfce7e0bced','191130_hard_2',4,'보행자가 없는 쪽 차로만 비어 있으면 진행할 수 있다.','횡단보도 전체가 보행자 통행 공간이므로 일부 차로만 비었다고 통과할 수 없습니다.',0),('2edfcff2-7c42-11f0-a0df-bcfce7e0bced','191130_hard_0',2,'만약 보행자가 횡단보도를 통행하려고 하는 상황(통행 직전의 상황)이면 운전자는 차량 신호에 맞춰 주행할 수 있다.','도로교통법 제27조는 보행자가 “통행하려고 하는 때”도 보호 대상으로 포함하고 있습니다.',0),('3bfd2423-7c40-11f0-a0df-bcfce7e0bced','87769_middle_2',3,'일단 정지하고 후진해서 우측 가장자리로 피한다.','제20조(진로 양보의 의무) 제2항 “좁은 도로에서 긴급자동차 외의 자동차가 서로 마주보고 진행할 때에는 다음 각 호의 구분에 따른 자동차가 도로의 우측 가장자리로 피하여 진로를 양보하여야 한다. - 2. 비탈진 좁은 도로 외의 좁은 도로에서 사람을 태웠거나 물건을 실은 자동차와 동승자(同乘者)가 없고 물건을 싣지 아니한 자동차가 서로 마주보고 진행하는 경우에는 동승자가 없고 물건을 싣지 아니한 자동차” 에 따라 동승자가 없는 운전자 차량이 진로를 양보해야 합니다.',1),('3f593ed2-8216-11f0-afd0-d843ae853d20','left_green_right_red_basic_1',1,'교차로 진입 전에 중앙선을 침범하여 좌회전 차로를 확보하는 것','도로교통법 제25조 제2항 “모든 차의 운전자는 교차로에서 좌회전을 하려는 때에는 미리 도로의 중앙선을 따라 서행하면서 교차로의 중심 안쪽을 이용하여 좌회전하여야 한다.” 중앙선 침범은 규정 위반이긴 하나, 직접적 충돌 위험과 같이 ‘가장 위험한 요인’이기 보다는 통행방법 위반에 속합니다.',0),('4214fe46-8226-11f0-afd0-d843ae853d20','192029_hard_0',1,'운전자 차량은 노란색 택시의 회전교차로 진입을 위해 서행하거나 필요 시에는 정지해야 한다.','도로교통법 제25조의2(회전교차로 통행방법) “모든 차의 운전자는 회전교차로에 진입하려는 경우에는 서행하거나 일시정지하여야 하며, 이미 진행하고 있는 다른 차가 있는 때에는 그 차에 진로를 양보하여야 한다.”에 따라 노란색 택시가 운전자 차량의 주행을 위해 서행하거나 일시정지 해야하므로 오답입니다.',0),('42642233-7c42-11f0-a0df-bcfce7e0bced','191130_hard_0',3,'횡단보도에서 보행자가 통행 중이면 운전자는 반드시 일시정지해야 한다.','도로교통법 제27조 제1항: “모든 차 또는 노면전차의 운전자는 보행자(제13조의2제6항에 따라 자전거등에서 내려서 자전거등을 끌거나 들고 통행하는 자전거등의 운전자를 포함한다)가 횡단보도를 통행하고 있거나 통행하려고 하는 때에는 보행자의 횡단을 방해하거나 위험을 주지 아니하도록 그 횡단보도 앞(정지선이 설치되어 있는 곳에서는 그 정지선을 말한다)에서 일시정지하여야 한다.”\r\n따라서 현재 영상에서의 운전자 차량의 행동은 명백히 법 위반입니다.',1),('439b843a-8216-11f0-afd0-d843ae853d20','left_green_right_red_basic_1',2,'좌회전 진입 시 신호등에 관계없이 보행자가 없으면 무리하게 진입하는 것','도로교통법 제5조(신호 또는 지시에 따를 의무) 제1항 “도로를 통행하는 보행자, 차마 또는 노면전차의 운전자는 교통안전시설이 표시하는 신호 또는 지시와 다음 각 호의 어느 하나에 해당하는 사람이 하는 신호 또는 지시를 따라야 한다.”에 따르면 보행자 유무와 관계없이 신호 준수 의무가 존재하며, 이를 무시하고 진입하는 것은 법 위반이지만, 좌회전 중 직진 차량과의 충돌보다는 보행자 충돌이나 신호위반 사고가 더 위험할 수 있으므로, 본 문항의 맥락상 \'최대 위험 상황\'으로 보기 어렵습니다.',0),('459a50bf-8226-11f0-afd0-d843ae853d20','192029_hard_0',2,'노란색 택시는 회전교차로에 진입할 때 우측 방향지시등을 켜고 진입해야 한다.','도로교통법 제25조의2(회전교차로 통행방법) 에 따르면 모든 차는 반시계방향으로 통행하며, 제38조(차의 신호)와 한국교통안전공단에서는 회전교차로에 진입할 때 좌측 방향지시등을 점등해야 한다고 명시하고 있습니다.',0),('480d8284-8226-11f0-afd0-d843ae853d20','192029_hard_0',3,'노란색 택시는 회전교차로에 진입할 때 좌측 방향지시등을 켜고 진입해야 한다.','도로교통법 제 25조의2, 제38조(차의 신호), 한국교통안전공단에 따르면 회전교차로에 진입할 때 좌측 방향지시등을 점등해야 하므로 정답입니다.',1),('497eb520-8226-11f0-afd0-d843ae853d20','192029_hard_0',4,'회전교차로를 통행할 때, 교차로를 진입하려는 차량이 이미 교차로 내를 주행 중인 차량보다 우선이기 때문에 해당 영상에서는 운전자 차량의 과실이 크다.','도로교통법 제25조의2(회전교차로 통행방법) “회전교차로에 진입하려는 경우, 이미 진행하고 있는 다른 차가 있는 때에는 그 차에 진로를 양보하여야 한다.”에 따라 이미 회전하고 있는 차량이 우선이므로 해당 영상에서는 노란색 택시의 사고과실이 큽니다.',0),('49c22585-8216-11f0-afd0-d843ae853d20','left_green_right_red_basic_1',3,'교차로 진입 전 속도를 줄여, 뒷 차량과의 충돌 가능성을 높이는 것','도로교통법 제25조 제2항과 제48조(안전운전 의무)에 따르면 운전자는 서행해야 할 의무가 있으며, 후행 차량과의 추돌은 서행이 아니라 후행 차량 과실 문제입니다. 즉, 위험은 존재하지만 ‘좌회전 자체의 리스크’라 보기 어렵습니다.',0),('4ccaedf0-7c40-11f0-a0df-bcfce7e0bced','87769_middle_2',4,'중앙선을 넘어 상대 차량을 피해간다.','제13조에 따른 우측 통행 의무를 위반하는 행위입니다.',0),('4cda2b09-8216-11f0-afd0-d843ae853d20','left_green_right_red_basic_1',4,'좌회전 진입 중, 교차로 중심 바깥쪽으로 진행해 오던 직진 차량을 방해하는 것','도로교통법 제25조 제2항 “좌회전하려는 때에는 (중략)  교차로의 중심 안쪽을 이용하여 좌회전하여야 한다. 다만, (중략) 지정된 곳에서는 교차로의 중심 바깥쪽을 통과할 수 있다.” \r\n중심 바깥쪽 통과는 예외적이며, 일반적 상황에서는 직진 차량과 충돌 위험을 높이는 매우 위험한 상황입니다.',1),('54cfad86-8229-11f0-afd0-d843ae853d20','149112_hard_0',1,'검은색 세단이 다른 차와 충돌해도 운전자의 책임이 있다.','도로교통법 제5조(신호·지시 준수 의무)에 따라 운전자는 신호에 맞춰 안전운전할 의무가 있습니다. 그러나 상대 차량이 다른 차와 충돌했다는 이유만으로 본 차량이 무조건 책임을 진다는 조항은 존재하지 않습니다. ',0),('5730b04a-8229-11f0-afd0-d843ae853d20','149112_hard_0',2,'우회전 중인 운전자 차량이 검은색 세단이 진입한 차선과 교차하는 경로를 진행하면, 운전자 차량이 충돌 방지 책임을 진다.','- 도로교통법 시행규칙에 따르면, 차량 신호등이 적색일 때는 반드시 일시정지 후 우회전해야 하며, 그 진행 경로가 다른 차의 경로와 교차할 경우 자신이 충돌을 방지해야 할 의무가 있습니다.\r\n    \r\n    따라서 교차로 내의 충돌이 발생할 경우, 우회전 중인 운전자 차량이 안전 조치를 취하지 않아 발생한 사고로 보고 책임이 인정됩니다.',1),('59529767-8229-11f0-afd0-d843ae853d20','149112_hard_0',3,'검은색 세단이 교차로에 진입한 경우, 우회전 중인 운전자 차량은 선행권이 없으므로 검은색 세단을 피해 차선을 변경한 후 주행한다.','선행권의 여부와 상관없이, 도로교통법과 도로교통법 시행규칙에 따라 우회전하는 운전자 차량은 우측 가장자리 서행 및 일시정지 적법 여부 (도로교통법 제25조 제1항 - 모든 차의 운전자는 교차로에서 우회전을 하려는 경우에는 미리 도로의 우측 가장자리를 서행하면서 우회전하여야 한다. 이 경우 우회전하는 차의 운전자는 신호에 따라 정지하거나 진행하는 보행자 또는 자전거등에 주의하여야 한다.)등 통행 방법을 준수해야 합니다.',0),('5a33973d-8229-11f0-afd0-d843ae853d20','149112_hard_0',4,'우회전 중인 운전자 차량은 교차로에서 우선권이 없으므로 검은색 세단과 충돌해도 책임이 없다.','우선권 유무와 관계없이 도로교통법상 운전자는 충돌 방지를 위한 주의의무가 있습니다. 도로교통법 제25조 제1항 “모든 차의 운전자는 교차로에서 우회전을 하려는 경우에는 미리 도로의 우측 가장자리를 서행하면서 우회전하여야 한다. 이 경우 우회전하는 차의 운전자는 신호에 따라 정지하거나 진행하는 보행자 또는 자전거등에 주의하여야 한다.”과 도로교통법 시행규칙 중 교차로 전방 신호등이 적색일 경우 반드시 일시정지 후 우회전해야 한다는 내용에 따라 운전자가 충돌 책임 원칙을 집니다.',0),('5e78dd4a-7c42-11f0-a0df-bcfce7e0bced','191130_hard_0',4,'차량이 우회전 중일 경우, 보행자 보호 의무는 면제된다.','우회전 중이라도 보행자 보호 의무는 면제되지 않습니다. 제27조는 교차로의 좌·우회전 여부와 무관하게 적용됩니다.',0),('6396695c-7c44-11f0-a0df-bcfce7e0bced','zigzag_basic_1',1,'노면표시는 도로관리자가 임의로 설치하는 안내선일 뿐, 법적 구속력은 없다.','도로교통법 제12조 및 제13조, 제31조 등에 따라 노면표시는 법적 효력을 가지며 단순 안내가 아닙니다.',0),('63ca0890-8240-11f0-afd0-d843ae853d20','87785_middle_2',1,'도로에서 1차로는 중앙선에 가장 가까이 있는 차로이다.','도로교통법 시행규칙 제16조(차로에 따른 통행구분)3항 “차로의 순위는 도로의 중앙선 쪽에 있는 차로부터 1차로로 한다. 다만, 일방통행도로에서는 도로의 왼쪽부터 1차로로 한다.” 에 따르면 중앙선에 가장 가까이 있는 차로부터 1차로입니다.',0),('646a79d4-8224-11f0-afd0-d843ae853d20','87768_middle_0',1,'전방 정체가 있으면 반드시 정지하고 주변 교통 상황을 살펴야 한다.','도로교통법 제31조(서행 또는 일시정지할 장소)는 전방 정체가 일반 도로에서 발생했을 때 반드시 정지할 의무를 규정하고 있지는 않습니다.',0),('6627439a-8240-11f0-afd0-d843ae853d20','87785_middle_2',2,'차량의 속도가 느려 뒤에 주행하는 다른 차량들의 통행을 방해할 가능성이 있을 때는 도로의 오른쪽 차로로 빠져야 한다. ','도로교통법 제20조(진로 양보의 의무)1항 “모든 차(긴급자동차는 제외한다)의 운전자는 뒤에서 따라오는 차보다 느린 속도로 가려는 경우에는 도로의 우측 가장자리로 피하여 진로를 양보하여야 한다. 다만, 통행 구분이 설치된 도로의 경우에는 그러하지 아니하다.” 에 따르면 느린 속도로 진행해 다른 차량의 통행을 방해할 우려가 있다면 도로의 우측으로 피해야 한다고 명시되어 있습니다.',0),('666b370a-8224-11f0-afd0-d843ae853d20','87768_middle_0',2,'전방 정체가 있을 때는 서행만 하면 된다.','도로교통법 제31조(서행 또는 일시정지할 장소)는 서행·정지의 의무가 특정 장소에 한정되며, 일반 도로에서는 서행만이 필수라는 규정이 없습니다.',0),('6872c3e5-821e-11f0-afd0-d843ae853d20','98453_basic_0',1,'반시계방향으로 운전하며, 진입 전에 속도를 줄여 다른 차에 진로를 양보한다.','도로교통법 제25조의2 제1항: “모든 차의 운전자는 회전교차로에서는 반시계방향으로 통행하여야 한다.”에 따르면, 회전교차로를 반시계방향으로 통행해야 합니다.\r\n도로교통법 제25조의2 제2항: “모든 차의 운전자는 회전교차로에 진입하려는 경우에는 서행하거나 일시정지하여야 하며, 이미 진행하고 있는 다른 차가 있는 때에는 그 차에 진로를 양보하여야 한다.”에 따르면, 진입 전 서행(또는 일시정지)하고, 다른 차량이 이미 진행 중이면 양보해야 합니다.\r\n도로교통법 제38조 제1항: “회전교차로에 진입하거나 회전교차로에서 진출하는 경우에는 손이나 방향지시기 또는 등화로써 그 행위가 끝날 때까지 신호를 하여야 한다.”에 따르면, 진입 시 방향지시를 해야 합니다. 따라서 A가 모든 법령을 충족하는 가장 적절한 행동입니다.',1),('68e5e097-8220-11f0-afd0-d843ae853d20','110371_basic_0',1,'하얀색 화물차를 앞질러야 하므로 바로 화물차의 좌측으로 통행한다.','도로교통법 제2조(정의) “29. ‘앞지르기’란 차의 운전자가 앞서가는 다른 차의 옆을 지나서 그 차의 앞으로 나가는 것을 말한다.”에 따르면 주차되어 있는 차량을 피해 주행하는 것은 앞지르기가 아닙니다. 또, 해당 영상에서는 화물차의 좌측에서 운전자 차량과 마주하는 방향으로 차량들이 주행하고 있으므로 운전자 차량이 바로 화물차의 좌측으로 통행하게 된다면 사고 위험이 높아집니다.',0),('6983d942-7c44-11f0-a0df-bcfce7e0bced','zigzag_basic_1',2,'노면표시는 신호등보다 우선 적용되므로, 신호등과 다를 경우 노면표시에 따라야 한다.','도로교통법 제5조(신호 준수)에 따르면 신호등이 노면표시와 다를 경우 신호등이 우선입니다.',0),('6b62dbe5-8240-11f0-afd0-d843ae853d20','87785_middle_2',3,'일방통행 도로에서는 차로가 존재하지 않는다.','도로교통법 시행규칙 제16조(차로에 따른 통행구분)3항 “차로의 순위는 도로의 중앙선 쪽에 있는 차로부터 1차로로 한다. 다만, 일방통행도로에서는 도로의 왼쪽부터 1차로로 한다.” 에 따르면 일반통행도로에서도 차로의 개념이 존재합니다. ',1),('6c1bbb04-7c47-11f0-a0df-bcfce7e0bced','110353_middle_2',1,'차량 신호등이 녹색일지라도 도로를 횡단하는 어린이가 있는지 주의하며 서행한다.','도로교통법 제12조(어린이 보호구역의 지정ㆍ해제 및 관리) “③ 차마 또는 노면전차의 운전자는 어린이 보호구역에서 제1항에 따른 조치를 준수하고 어린이의 안전에 유의하면서 운행하여야 한다.”와  제 49조(모든 운전자의 준수사항 등) “2. 다음 각 목의 어느 하나에 해당하는 경우에는 일시정지할 것. 가. 어린이가 보호자 없이 도로를 횡단할 때, 어린이가 도로에서 앉아 있거나 서 있을 때 또는 어린이가 도로에서 놀이를 할 때 등 어린이에 대한 교통사고의 위험이 있는 것을 발견한 경우” 에 따라 언제든 즉각 일시정지할 수 있도록 서행해야한다.',1),('6cb56796-821e-11f0-afd0-d843ae853d20','98453_basic_0',2,'직진 방향으로 진행하며, 다른 차에 양보하지 않아도 된다.','도로교통법 제25조의2 제2항에 따라 “이미 진행하고 있는 다른 차가 있는 때에는 그 차에 진로를 양보하여야 한다.”에 따르면,직진 방향으로 진행해도 다른 차가 있으면 양보해야 하므로 B는 옳지 않습니다.',0),('6d9b89d9-8220-11f0-afd0-d843ae853d20','110371_basic_0',2,'맞은편에서 주행하는 차량들이 지나가기를 기다렸다가 화물차의 좌측으로 통행한다.','운전자 차량과 마주보는 방향으로 주행하는 차량들을 피해 화물차 뒤에 잠시 정지했다가 더 이상 맞은편 차량이 없을 때 주행해야지 사고위험을 줄일 수 있기 때문에 해당 선지가 정답입니다.',1),('6e7e47f7-8240-11f0-afd0-d843ae853d20','87785_middle_2',4,'편도 4차로 고속도로에서 1차로는 앞지르기를 하려는 승용차 및 승합자동차가 통행할 수 있다.','도로교통법 시행규칙 [별표 9] “고속도로 편도 3차로 이상 - 1차로에서 통행할 수 있는 차종 : 앞지르기를 하려는 승용자동차 및 앞지르기를 하려는 경형·소형·중형 승합자동차. 다만, 차량통행량 증가 등 도로상황으로 인하여 부득이하게 시속 80킬로미터 미만으로 통행할 수밖에 없는 경우에는 앞지르기를 하는 경우가 아니라도 통행할 수 있다.”에 맞는 부합한 설명이므로 오답입니다.',0),('6ef7e502-8224-11f0-afd0-d843ae853d20','87768_middle_0',3,'전방 정체가 있을 때 원활한 교통 진행을 위해서 차선 변경을 해야 한다.','전방 정체 시에 차선을 변경해야 한다는 규정은 존재하지 않습니다. 오히려 도로에 정체가 생긴 상황에서의 무리한 차선 변경으로 인한 사고 위험이 높아질 가능성이 있습니다.',0),('6fe4111f-8224-11f0-afd0-d843ae853d20','87768_middle_0',4,'전방 정체가 있을 때 정지해도 된다.','- 도로교통법 제31조(서행 또는 일시정지할 장소)에 따르면 특정 장소에서만 일시정지가 요구되는 것을 명시하고 있습니다. 일반 도로에서 발생한 전방 정체(예: 차량 밀집, 교통 체증)는 이 조문에 규정된 “특정 장소”에 해당하지 않으므로, 법적으로 **정지를 해야 할 강제적 근거가 존재하지 않습니다.**\r\n    \r\n    따라서 **정지해도(즉, 정지해도 된다)** 라는 선택지가 도로교통법의 요구사항과 가장 부합합니다. 정지를 선택해도 법적으로 금지된 것은 아니며, 상황에 따라 필요하면 정지할 수 있습니다.',1),('70fca314-7c47-11f0-a0df-bcfce7e0bced','110353_middle_2',2,'어린이의 하차를 위해서라면 잠시 정차할 수 있다.','위반입니다. 제32조(정차 및 주차의 금지) “모든 차의 운전자는 다음 각 호의 어느 하나에 해당하는 곳에서는 차를 정차하거나 주차하여서는 아니 된다. 다만, 이 법이나 이 법에 따른 명령 또는 경찰공무원의 지시를 따르는 경우와 위험방지를 위하여 일시정지하는 경우에는 그러하지 아니하다… (중략) 8. 시장등이 제12조제1항에 따라 지정한 어린이 보호구역”에 의해 하차 목적이라도 어린이 보호 구역 내에서는 주·정차 금지됩니다.',0),('7108f6fe-8220-11f0-afd0-d843ae853d20','110371_basic_0',3,'맞은편에서 주행하는 차량들과의 사고 위험을 경고하기 위해 경음기를 반복적으로 사용한다.','도로교통법 제21조(앞지르기 방법 등) 제3항 “제1항과 제2항의 경우 앞지르려고 하는 모든 차의 운전자는 반대방향의 교통과 앞차 앞쪽의 교통에도 주의를 충분히 기울여야 하며, 앞차의 속도ㆍ진로와 그 밖의 도로상황에 따라 방향지시기ㆍ등화 또는 경음기(警音機)를 사용하는 등 안전한 속도와 방법으로 앞지르기를 하여야 한다.” 에 따르면 앞지르기를 하는 경우에는 경음기 사용이 허용되지만, 해당 상황은 주차되어 있는 차량을 피해 주행하는 것이므로 앞지르기가 아니고, 도로교통법 제49조(모든 운전자의 준수사항 등) “운전자는 정당한 사유 없이 다음 각 목의 어느 하나에 해당하는 행위를 하여 다른 사람에게 피해를 주는 소음을 발생시키지 아니할 것 - (중략) 반복적이거나 연속적으로 경음기를 울리는 행위 (중략) ”에 따르면 반복적, 연속적으로 경음기를 울리는 행위를 금하고 있습니다.',0),('713fb80a-821e-11f0-afd0-d843ae853d20','98453_basic_0',3,'회전교차로에 진입할 때 신호를 하지 않아도 된다.','도로교통법 제38조 제1항에 따라 “회전교차로에 진입하거나 회전교차로에서 진출하는 경우에는 손이나 방향지시기 또는 등화로써 그 행위가 끝날 때까지 신호를 하여야 한다.”에 따르면, 신호를 하지 않으면 법 위반이므로 C는 틀린 답변입니다.',0),('71ce5f89-7c44-11f0-a0df-bcfce7e0bced','zigzag_basic_1',3,'운전자는 노면표시가 있으면 반드시 그 지시에 따라야 한다.','도로교통법 제13조에 따르면 운전자는 안전표시(노면표시 포함)의 지시에 따라야 합니다.',1),('738f516d-8220-11f0-afd0-d843ae853d20','110371_basic_0',4,'맞은편에서 주행하는 차량들이 지나가기를 기다릴 때, 도로의 좌측 가장자리로 피하여 진로를 양보한다.','도로교통법 제20조(진로 양보의 의무) “2. 좁은 도로에서 긴급자동차 외의 자동차가 서로 마주보고 진행할 때에는 다음 각 호의 구분에 따른 자동차가 도로의 우측 가장자리로 피하여 진로를 양보하여야 한다.”에 따르면 좁은 도로에서 진로를 양보할 때 좌측 가장자리로 피하여 양보하는 것은 옳지 않습니다. 운전자의 진행 방향을 기준으로 우측 가장자리로 피하여 진로를 양보해야 합니다.',0),('74fc81ba-7c47-11f0-a0df-bcfce7e0bced','110353_middle_2',3,'신호기가 없는 횡단보도 앞에서는 보행자가 없더라도 반드시 일시정지 후 진행한다.','도로교통법 제27조(보행자의 보호) “⑦ 모든 차 또는 노면전차의 운전자는 제12조제1항에 따른 어린이 보호구역 내에 설치된 횡단보도 중 신호기가 설치되지 아니한 횡단보도 앞(정지선이 설치된 경우에는 그 정지선을 말한다)에서는 보행자의 횡단 여부와 관계없이 일시정지하여야 한다.” 에 의해 어린이 보호구역 내 신호기가 없는 횡단보도 앞에서는 보행자 유무와 관계없이 일시정지해야 합니다.',1),('75cd83cc-8218-11f0-afd0-d843ae853d20','154060_basic_0',1,'전조등(차량 앞의 헤드라이트) 등의 등화를 반드시 키고 터널 내에서 운행한다.','도로교통법 제37조 제3항에 따르면 ‘터널 안을 운행하거나 고장 또는 그 밖의 부득이한 사유로 터널 안 도로에서 차 또는 노면전차를 정차 또는 주차하는 경우’에는 전조등(前照燈), 차폭등(車幅燈), 미등(尾燈)을 켜야 합니다. 따라서 조명이 어두워진 터널 진입 시 반드시 등화를 해야 합니다.',1),('75d4a207-821e-11f0-afd0-d843ae853d20','98453_basic_0',4,'회전교차로에 진입하기 전 다른 차가 없으면 즉시 빠르게 통과한다.','도로교통법 제25조의2 제2항에서 “서행하거나 일시정지하여야 하며, 이미 진행하고 있는 다른 차가 있는 때에는 그 차에 진로를 양보하여야 한다.”에 따르면 다른 차량이 없더라도 서행(혹은 일시정지) 없이 빠르게 통과하면 위험을 초래하고 법령과 맞지 않습니다.\r\n또한 도로교통법 제26조 제2항에서는 “교통정리가 없는 교차로에 진입하려는 경우에는 양보해야 한다.”에 따르면 회전교차로가 교통정리가 없는 교차로라면 양보가 필요합니다.\r\n따라서 D 역시 부적절한 운전 행위입니다.',0),('767aa43e-7c44-11f0-a0df-bcfce7e0bced','zigzag_basic_1',4,'노면표시는 보행자에게만 해당되며 차량 운전자에게는 법적 효력이 없다.','노면표시는 보행자와 운전자 모두에게 적용됩니다.',0),('778ba15a-7c46-11f0-a0df-bcfce7e0bced','110353_middle_1',1,'공사 구간 진입 전, 우측 차로가 작업 차량으로 완전히 차단되어 있어 부득이하게 중앙선을 넘어 좌측 차로로 진행한 경우','도로교통법 제13조(차마의 통행) “④ 차마의 운전자는 제3항에도 불구하고 다음 각 호의 어느 하나에 해당하는 경우에는 도로의 중앙이나 좌측 부분을 통행할 수 있다. 2. 도로의 파손, 도로공사나 그 밖의 장애 등으로 도로의 우측 부분을 통행할 수 없는 경우”에 따라 도로공사로 인해 우측 차선을 통행할 수 없는 경우에는 중앙선을 넘어 좌측 부분을 이용할 수 있습니다. 따라서 위반이 아닙니다.',0),('79d8c6ec-8218-11f0-afd0-d843ae853d20','154060_basic_0',2,'터널 안에서 다른 차량의 통행을 방해하지 않도록 속도를 조금 높여 터널 안을 빠르게 통과한다.','도로교통법 제65조(고속도로 진입 시의 우선순위) 등에서는 고속도로에 진입할 때 다른 차량의 통행을 방해하지 말라고 명시하지만, 속도를 증가시키는 행위가 필요하다고 규정하고 있지 않습니다. 터널 내에서는 등화가 필수이며, 속도 조절은 법률상의 요구 사항이 아닙니다.',0),('7c566f3a-7c46-11f0-a0df-bcfce7e0bced','110353_middle_1',2,'공사 구간 진입 전, 교통정리 중인 경찰관이 수신호로 직진을 지시하지만, 전방 신호등이 적색이기 때문에 신호등 지시에 따라 정지','위반입니다. 도로교통법 제5조(신호 또는 지시에 따를 의무) “① 도로를 통행하는 보행자, 차마 또는 노면전차의 운전자는 교통안전시설이 표시하는 신호 또는 지시와 다음 각 호의 어느 하나에 해당하는 사람이 하는 신호 또는 지시를 따라야 한다.  \r\n1. 교통정리를 하는 경찰공무원(의무경찰을 포함한다. 이하 같다) 및 제주특별자치도의 자치경찰공무원(이하 “자치 경찰 공무원”이라 한다)\r\n2. 경찰공무원(자치경찰공무원을 포함한다. 이하 같다)을 보조하는 사람으로서 대통령령으로 정하는 사람(이하 “경찰보조자”라 한다) “에 따르면 운전자는 경찰관이나 교통을 유도하는 자(공사 현장 작업자 포함)의 신호나 지시에 따라야 합니다. 신호등보다 경찰관 또는 교통 유도자의 수신호가 우선이기 때문에 수신호가 직진 지시를 해 이에 따라 정지한 것은 지시에 불응한 것으로 간주됩니다.',1),('7c6bb921-821a-11f0-afd0-d843ae853d20','154060_basic_2',1,'터널 진입 전, 명순응에 대비하여 색안경을 벗고 밤에 준하는 등화를 켠다.','“명순응 - 어두운 곳에서 밝은 곳으로 나왔을 때 점차 밝은 빛에 적응하는 현상” 이므로 명순응이 아닌 터널을 진입할 때는 밝은 곳에서 어두운 곳으로 들어갈 때 처음에는 보이지 않던 것이 시간이 지나면 보이기 시작하는 현상인 암순응에 대비하는 것이 맞으며, 도로교통법 제37조 제3항에 따르면 ‘터널 안을 운행하거나 고장 또는 그 밖의 부득이한 사유로 터널 안 도로에서 차 또는 노면전차를 정차 또는 주차하는 경우’에는 전조등(헤드라이트), 차폭등(車幅燈), 미등(尾燈)을 켜야 합니다.',0),('7e72ab75-847a-11f0-bb06-d843ae853d20','zigzag_basic_3',1,'중앙선 표시는 노란색 실선 / 노란색 점선 / 노란색 실선과 점선의 복선 / 노란색 실선 두 개로 총 4가지 종류가 있다.','도로교통법 시행규칙 [별표 6]에 따르면 중안선의 종류가 황색 실선, 황색 점선, 황색 실선과 점선의 복선, 실선의 황색복선 이렇게 4가지 종류가 있음을 명시하고 있습니다.',1),('806fe4fd-7c47-11f0-a0df-bcfce7e0bced','110353_middle_2',4,'어린이 보호구역은 모두 시속 30km로 제한되므로, 이 속도를 넘지 않으면 된다.','틀린 선지입니다. 지역별로 20~40km/h 등 제한 속도가 달라질 수 있습니다. 시속 30 km과 다른 통행 속도로 설정된 어린이 보호구역도 다수 존재합니다.',0),('80d7bd37-821f-11f0-afd0-d843ae853d20','98453_basic_2',1,'차로 변경이 필요하면 따로 신호 없이 변경 가능하다.','- 도로교통법 제38조(차의 신호)\r\n    \r\n    “① 모든 차의 운전자는 좌회전ㆍ우회전ㆍ횡단ㆍ유턴ㆍ서행ㆍ정지 또는 후진을 하거나 같은 방향으로 진행하면서 진로를 바꾸려고 하는 경우와 회전교차로에 진입하거나 회전교차로에서 진출하는 경우에는 손이나 방향지시기 또는 등화로써 그 행위가 끝날 때까지 신호를 하여야 한다. <개정 2022. 1. 11.>” 제1항에 따르면 차선 변경 시에 방향지시등을 킬 것을 명시하고 있습니다.',0),('81353d51-821a-11f0-afd0-d843ae853d20','154060_basic_2',2,'터널 안 차선이 하얀색 실선이고, 운전자 차량의 앞 차량이 느리게 주행 중이면 차로 변경 및 앞 차량 추월이 가능하다.','도로교통법 제 22조 3항에 따르면 터널 안에서는 앞지르기가 금지되어 있으며, 앞지르기를 위해서는 차로 변경이 필수이기 때문에 터널 내의 차로 변경이 금지되어 있습니다.',0),('815357aa-847a-11f0-bb06-d843ae853d20','zigzag_basic_3',2,'주차금지표시, 정차ᆞ주차금지표시는 하얀색으로 표시되어 있다.','도로교통법 시행규칙 [별표 6] “중앙선표시, 주차금지표시, 정차ᆞ주차금지표시, 정차금지지대표시, 보호구역 기점ᆞ종점 표시의 테두리와 어린이보호구역 횡단보도 및 안전지대 중 양방향 교통을 분리하는 표시: 노란색”에 따라 주차금지표시, 정차ᆞ주차금지표시는 노란색입니다.',0),('81cffb3a-7c46-11f0-a0df-bcfce7e0bced','110353_middle_1',3,'진로 변경이 금지된 흰색 실선이지만, 전방에 공사 구간이 있어 차선을 변경한 경우','위반이 아닙니다. 도로교통법 제 14조(차로의 설치 등) “⑤ 차마의 운전자는 안전표지가 설치되어 특별히 진로 변경이 금지된 곳에서는 차마의 진로를 변경하여서는 아니 된다. 다만, 도로의 파손이나 도로공사 등으로 인하여 장애물이 있는 경우에는 그러하지 아니하다.” 에 따라 원칙적으로 흰색 실선 구간에서는 진로 변경이 금지됩니다. 그러나 도로공사로 장애물이 있을 경우에는 예외적으로 차선을 변경할 수 있습니다.',0),('82961a3a-8213-11f0-afd0-d843ae853d20','zigzag_basic_2',1,'양보운전의 노면표시는 흰색 마름모 ’◇’(다이아몬드 모양)로 표시한다.','도로교통법 시행규칙 [별표 6]에 따르면 양보운전 노면표시는 역삼각형 ‘▽’ 입니다. 흰색 마름모는 전방에 횡단보도가 있음을 알리는 노면표시입니다.',0),('8343ec07-8218-11f0-afd0-d843ae853d20','154060_basic_0',3,'어두운 곳에서의 맞은 편 차량 운전자의 눈부심을 줄이기 위해 전조등(차량 앞의 헤드라이트)을 꺼야한다.','도로교통법 제37조 제2항은 ‘차량이 터널에 진입할 때 등화를 조절해야 한다’는 내용을 포함하고 있으나, 앞등을 끄는 것은 등화 의무를 위반하는 행위이며, 제37조 제1항·제3항이 요구하는 등화가 반드시 켜져 있어야 함을 명시합니다. 따라서 앞등을 끄는 것은 부적절합니다.',0),('839874bd-847a-11f0-bb06-d843ae853d20','zigzag_basic_3',3,'소방시설 주변 정차․주차 금지 표시와 전용차로표시는 파란색으로 표시되어 있다.','도로교통법 시행규칙 [별표 6] “소방시설 주변 정차·주차금지표시 및 보호구역(어린이ᆞ노인ᆞ장애인) 또는 주거지역 안에 설치하는 속도제한표시의 테두리선: 빨간색 또는 흰색”, “전용차로표시 및 노면전차전용로표시: 파란색”에 따라 소방시설 주변 정차․주차 금지 표시는 빨간색 또는 흰색이고, 전용차로표시는 파란색입니다.',0),('848fe90f-821f-11f0-afd0-d843ae853d20','98453_basic_2',2,'회전교차로는 차선 변경 규칙이 적용되지 않는다.','회전교차로도 도로에 포함되므로 일반 차로 변경 규정이 적용됩니다.',0),('84a5befa-821a-11f0-afd0-d843ae853d20','154060_basic_2',3,'앞 차와의 안전거리를 유지하면서 사고 위험을 경고하기 위해 경적을 수시로 울린다.','터널 내에서는 사고 위험이 커지므로 (결빙, 2차사고 등) 교통사고를 예방하기 위해 터널 안에서 일반도로보다 안전거리를 더 확실하게 확보하고 앞 차량의 급제동에 대한 대비 또한 필요합니다. ',0),('850277bc-7c3e-11f0-a0df-bcfce7e0bced','87769_middle_1',1,'승용차가 대형차보다 작으므로 무조건 후진해야 한다.','도로교통법 제20조는 차량 크기에 따른 무조건 양보 규정을 두고 있지 않습니다.',0),('871c8c22-84ae-11f0-bb06-d843ae853d20','busstop_hard_1',1,'중앙 버스전용차로는 운영 시간 외에는 일반 차량도 통행 가능하다.','중앙 버스전용차로는 시간제 운영되는 가로변 버스전용차로와 달리, 운영 시간과 관계없이 365일 24시간 연중 통제로 일반 차량 통행이 절대 불가합니다.',0),('8730af2d-821a-11f0-afd0-d843ae853d20','154060_basic_2',4,'터널 진입 전 암순응에 대비하여 등화를 켠다.','터널을 진입할 때는 밝은 곳에서 어두운 곳으로 들어갈 때 처음에는 보이지 않던 것이 시간이 지나면 보이기 시작하는 현상인 암순응에 대비하는 것이 맞으며, 도로교통법 제37조 제3항에 따르면 ‘터널 안을 운행하거나 고장 또는 그 밖의 부득이한 사유로 터널 안 도로에서 차 또는 노면전차를 정차 또는 주차하는 경우’에는 전조등(헤드라이트), 차폭등(車幅燈), 미등(尾燈)을 켜야 하므로 해당 선지가 정답입니다.',1),('88263dc6-8213-11f0-afd0-d843ae853d20','zigzag_basic_2',2,'양보운전의 노면표시는 흰색 마름모 ’▽’(역삼각형 모양)로 표시한다','도로교통법 시행규칙 [별표 6]에 따르면 양보운전 노면표시는 역삼각형 ‘▽’ 입니다.',1),('896e8f51-821f-11f0-afd0-d843ae853d20','98453_basic_2',3,'차선 변경 시 반드시 방향지시등(깜빡이)을 켜고, 안전이 확보된 후에 변경해야 한다.','- 도로교통법 제38조(차의 신호)\r\n    \r\n    “① 모든 차의 운전자는 좌회전ㆍ우회전ㆍ횡단ㆍ유턴ㆍ서행ㆍ정지 또는 후진을 하거나 같은 방향으로 진행하면서 진로를 바꾸려고 하는 경우와 회전교차로에 진입하거나 회전교차로에서 진출하는 경우에는 손이나 방향지시기 또는 등화로써 그 행위가 끝날 때까지 신호를 하여야 한다. <개정 2022. 1. 11.>” 제1항에 따르면 차선 변경 시에 방향지시등을 키고, 안전을 확보한 이후에 차선을 변경해야 합니다.',1),('8975580d-84ae-11f0-bb06-d843ae853d20','busstop_hard_1',2,'중앙 버스전용차로는 도로의 중앙차로뿐 아니라 가로변에도 설치되는 유형이다.','중앙 버스전용차로는 도로의 중앙부에 설치되는 유형이며, 가로변에는 가로변 버스전용차로가 설치됩니다. 두 개는 별개의 유형입니다.',0),('8af0375a-847a-11f0-bb06-d843ae853d20','zigzag_basic_3',4,'어린이ᆞ노인ᆞ장애인 등의 보호구역은 노란색으로 표시되어 있다.','도로교통법 시행규칙 [별표 6] “영 제10조의3제2항에 따라 설치하는 소방시설 주변 정차·주차금지표시 및 보호구역(어린이ᆞ노인ᆞ장애인) 또는 주거지역 안에 설치하는 속도제한표시의 테두리선: 빨간색 또는 흰색” 에 따라 어린이ᆞ노인ᆞ장애인 등의 보호구역은 빨간색 또는 흰색으로 표시되어 있습니다.',0),('8c6e975d-8218-11f0-afd0-d843ae853d20','154060_basic_0',4,'터널을 주행할 때, 원활한 통행을 위하여 앞 차량을 추월(앞지르기)하여 주행할 수 있다.','도로교통법 제22조(앞지르기 금지의 시기 및 장소)에 따르면 터널 안에서는 다른 차를 앞지르지 못하게 규정되어 있으므로 오답입니다.',0),('8cf78767-84ae-11f0-bb06-d843ae853d20','busstop_hard_1',3,'중앙 버스전용차로 내 일반 차량이 승객을 태우거나 내리기 위해 일시 정차하는 것은 허용된다.','- 일반 차량의 중앙 버스전용차로 진입 또는 정차는 **원칙적으로 금지**됩니다. 예외적으로 허용되는 것은 **택시가 승객의 승·하차를 위한 목적**일 뿐이며, 이는 **가로변 버스전용차로 또는 택시의 승강 활동을 위한 규정에 해당**하며, 중앙 차로에서는 적용되지 않습니다.\r\n    \r\n    도로교통법 시행령 제10조(전용차로 통행 예외)에 따르면, 예외 사유(택시 승·하차 포함)는 “전용차로통행차의 통행에 장애를 주지 않는 범위에서”만 적용됩니다. 중앙버스전용차로는 일반 차량에 대해 적용되지 않습니다.',0),('8e4bcdcb-8213-11f0-afd0-d843ae853d20','zigzag_basic_2',3,'회전교차로에 진입하기 직전 최소 30미터 전에서 손으로 신호를 보내거나 방향지시등(깜빡이)를 켜야 한다.','도로교통법 시행령 [별표 2] “회전교차로에 진입하려는 때 - 그 행위를 하려는 지점에 이르기 전 30미터 이상의 지점에 이르렀을 때 : 왼팔을 수평으로 펴서 차체의 왼쪽 밖으로 내밀거나 오른팔을 차체의 오른쪽 밖으로 내어 팔꿈치를 굽혀 수직으로 올리거나 왼쪽의 방향지시기 또는 등화를 조작할 것”에 적합한 행위이므로 해당 선지는 정답입니다.',1),('8ec1cc39-84ae-11f0-bb06-d843ae853d20','busstop_hard_1',4,'중앙 버스전용차로는 365일 24시간 연중 운영되며, 일반 차량은 통행이 엄격히 금지된다.','중앙 버스전용차로는 하루 중 어느 때든, 요일 불문하고 일반 차량은 절대 사용할 수 없습니다. 이는 다른 유형과 구분되는 특징이므로, 해당 선지가 정답입니다.',1),('9057dc6a-8225-11f0-afd0-d843ae853d20','busstop_hard_0',1,'보행자가 무단횡단했으므로 운전자는 책임이 없다.','도로교통법 제27조(보행자 보호의무), 보행자가 무단횡단하더라도 운전자는 보행자를 보호해야 할 주의의무 있음. 따라서 “책임 없다”는 잘못된 해석입니다.',0),('9096eaad-84b2-11f0-bb06-d843ae853d20','149112_hard_1',1,'노란불 깜빡임 - 차량은 다른 교통 또는 안전표지에 주의하면서 주행 가능하다.','도로교통법 시행규칙 [별표 2] “차량 신호등 - 황색 등화의 점멸 : 차마는 다른 교통 또는 안전표지의 표시에 주의하면서 진행할수 있다.” 에 따라 선지 1번은 정답입니다.',1),('9112759b-821f-11f0-afd0-d843ae853d20','98453_basic_2',4,'회전교차로 내의 사고 예방을 위해 차선 변경은 금지되어 있으므로 현재 차선을 유지해야 한다.','도로교통법 상 회전교차로에서의 차선 변경 금지가 규정되어 있지 않습니다.',0),('922dda5d-8226-11f0-afd0-d843ae853d20','192029_hard_1',1,'회전교차로에서는 시계방향으로 돌며, 먼저 진입한 차량에게 통행 우선권이 있다.','도로교통법 제25조2(회전교차로 통행방법)제1항 “모든 차의 운전자는 회전교차로에서는 반시계방향으로 통행하여야 한다.”에 따라 시계방향으로 돈다는 설명은 잘못되었습니다.',0),('92589eb5-8225-11f0-afd0-d843ae853d20','busstop_hard_0',2,'버스 전용차로 주행 자체가 위법이 될 수 있다.','도로교통법 제15조 제2항 “버스전용차로 지정 구간에서는 승용차 등은 진입할 수 없다.” 따라서 버스전용차로 주행은 위반입니다.',1),('9292cfdd-84b2-11f0-bb06-d843ae853d20','149112_hard_1',2,'빨간불 - 보행자는 주변의 차량을 살핀 후 주의하면서 횡단보도를 횡단할 수 있다.','도로교통법 시행규칙 [별표 2] “보행 신호등 - 적색의 등화 : 보행자는 횡단보도를 횡단하여서는 아니 된다.” 에 따라 보행자는 적색 신호에서 횡단이 불가능합니다.',0),('94804f7e-8226-11f0-afd0-d843ae853d20','192029_hard_1',2,'회전교차로 진입 시 속도를 줄이거나 일시정지하고, 회전 중인 차량이 없을 경우 진입할 수 있다.','도로교통법 제25조2(회전교차로 통행방법)제1항 “모든 차의 운전자는 회전교차로에 진입하려는 경우에는 서행하거나 일시정지하여야 하며, 이미 진행하고 있는 다른 차가 있는 때에는 그 차에 진로를 양보하여야 한다.”에 부합하는 설명이므로 해당 선지가 정답입니다.',1),('954139c8-8225-11f0-afd0-d843ae853d20','busstop_hard_0',3,'보행자가 도로를 점유했으므로 운전자의 위반은 성립하지 않는다.','보행자가 도로에 진입했더라도 운전자는 도로교통법 제27조에 따른 보행자 보호의무를 면할 수 없습니다.',0),('96e4069b-8225-11f0-afd0-d843ae853d20','busstop_hard_0',4,'버스 전용차로는 일시적으로 진입해도 무방하다.','버스전용차로는 “예외 차량(버스·승합차 등)” 외에는 어떠한 경우에도 진입 불가(도로교통법 제15조). “잠깐 진입” 허용되지 않습니다.',0),('96f46da0-7c46-11f0-a0df-bcfce7e0bced','110353_middle_1',4,'제한속도를 준수하고 전방 차량과의 충분한 안전거리를 유지하면서, 우측 차로의 작업 구간을 피해 좌측 차로로 변경하여 서행으로 통과한 경우','위반이 아닙니다. 도로교통법 제48조 제1항(안전운전 의무)에 따라 제한속도를 준수하고, 안전거리를 확보한 상태에서 차로를 변경해 공사구간을 피하는 것은 안전운전 원칙에 부합합니다.',0),('973065bf-84b2-11f0-bb06-d843ae853d20','149112_hard_1',3,'초록색 화살표 신호 - 차량은 화살표 방향으로 주행 가능하다.','도로교통법 시행규칙 [별표 2] “차량 신호등 - 녹색화살표의 등화 : 차마는 화살표로 지정한 차로로 진행할 수 있다.” 에 따라 선지 3번은 정답입니다.',1),('98a687f4-84b2-11f0-bb06-d843ae853d20','149112_hard_1',4,'노란불 - 차량이 이미 교차로에 들어가고 있는 경우에는 교차로 안에서 정지해야 한다.','도로교통법 시행규칙 [별표 2] “차량 신호등 - 황색의 등화 : 차마는 정지선이 있거나 횡단보도가 있을 때에는 그 직전이나 교차로의 직전에 정지하여야 하며, 이미 교차로에 차마의 일부라도 진입한 경우에는 신속히 교차로 밖으로 진행하여야 한다.” 에 따라 차량이 이미 교차로에 진입했더라도 신속하게 교차로 밖으로 나와야 합니다.',0),('98a9c8de-84af-11f0-bb06-d843ae853d20','busstop_hard_3',1,'승차정원 4인승인 승용차에 4인이 탑승한 차량','도로교통법 시행령 별표1에 따르면 고속도로의 버스전용차로는 9인승 이상 승용자동차 및 승합자동차(승용자동차 또는 12인승 이하의 승합자동차는 6명 이상이 승차한 경우로 한정한다.) 만이 통행 가능하므로 오답입니다.',0),('9913ada7-8226-11f0-afd0-d843ae853d20','192029_hard_1',3,'회전교차로 진입 전 좌측 방향지시등을 켜는 것은 선택사항이며, 진출 시에만 켜도 무방하다.','도로교통법 시행령 [별표 2] 신호의 시기 및 방법의 “회전교차로에 진입하려는 때 - 30미터 전에 왼쪽의 방향지시기 또는 등화를 조작할 것”, “회전교차로에서 진출하려는 때 - 진출 시에 오른쪽 방향지시기 또는 등화를 조작할 것”에 따라 회전교차로에 진입하거나 진출할 경우 모두 방향지시등을 의무적으로 켜야합니다.',0),('9a62f1c9-8226-11f0-afd0-d843ae853d20','192029_hard_1',4,'회전교차로 내 통행 시 우선권은 진입 차량에게 있으며, 교차로 내의 이미 회전하고 있는 차량이 양보해야 한다.','도로교통법 제25조2(회전교차로 통행방법)제1항 “모든 차의 운전자는 회전교차로에 진입하려는 경우에는 서행하거나 일시정지하여야 하며, 이미 진행하고 있는 다른 차가 있는 때에는 그 차에 진로를 양보하여야 한다.”에 따르면 통행 우선권이 있는 차량은 회전 차량입니다. 따라서 진입하려는 차량이 양보해야 합니다.',0),('9ac92963-84af-11f0-bb06-d843ae853d20','busstop_hard_3',2,'승차정원 9인승 이상 승용차에 7인이 승차한 차량','도로교통법 시행령 별표1에 따르면 고속도로에서의 버스전용차로는 9인승 이상 승용자동차 및 승합자동차(승용자동차 또는 12인승 이하의 승합자동차는 6명 이상이 승차한 경우로 한정한다)가 통행 가능하므로 7인, 즉 6인 이상이 승차했기 때문에 통행 가능합니다.',1),('9c40cf8d-8216-11f0-afd0-d843ae853d20','left_green_right_red_basic_2',1,'교차로에 동시에 들어가려고 할 때 운전자는 좌측도로의 차에 진로를 양보해야 한다.','도로교통법 제26조(교통정리가 없는 교차로에서의 양보운전)3항 “교통정리를 하고 있지 아니하는 교차로에 동시에 들어가려고 하는 차의 운전자는 우측도로의 차에 진로를 양보하여야 한다.”에 따라 좌측도로의 차가 아니라 우측도로의 차에 진로를 양보해야 합니다.',0),('9cfcfb31-84af-11f0-bb06-d843ae853d20','busstop_hard_3',3,'승차정원 10인승인 승합차에 5인이 승차한 차량','도로교통법 시행령 별표1에 따르면 고속도로의 버스전용차로는 9인승 이상 승용자동차 및 승합자동차(승용자동차 또는 12인승 이하의 승합자동차는 6명 이상이 승차한 경우로 한정한다.) 만이 통행 가능하므로 오답입니다.',0),('9e168daa-84af-11f0-bb06-d843ae853d20','busstop_hard_3',4,'승차정원 12인승인 승합차에 5인이 승차한 차량','도로교통법 시행령 별표1에 따르면 고속도로의 버스전용차로는 9인승 이상 승용자동차 및 승합자동차(승용자동차 또는 12인승 이하의 승합자동차는 6명 이상이 승차한 경우로 한정한다.) 만이 통행 가능하므로 오답입니다.',0),('9ff2500a-8213-11f0-afd0-d843ae853d20','zigzag_basic_2',4,'회전교차로에서 나갈 때는 손으로 신호를 보내거나 왼쪽의 방향지시등(왼쪽 깜빡이)를 켜야 한다.','도로교통법 시행령 [별표 2] “회전교차로에서 진출하려는 때 - 그 행위를 하려는 때 : 오른팔을 수평으로 펴서 차체의 오른쪽 밖으로 내밀거나 왼팔을 차체의 왼쪽 밖으로 내어 팔꿈치를 굽혀 수직으로 올리거나 오른쪽의 방향지시기 또는 등화를 조작할 것”에 따라 회전교차로에 나갈 때는 오른쪽의 방향지시등(오른쪽 깜빡이)를 켜야하므로 오답입니다.',0),('a21bde0f-8216-11f0-afd0-d843ae853d20','left_green_right_red_basic_2',2,'교차로에 선진입한 차량이 통과한 뒤 우회전한다.','도로교통법 제26조(교통정리가 없는 교차로에서의 양보운전)1항 “교통정리를 하고 있지 아니하는 교차로에 들어가려고 하는 차의 운전자는 이미 교차로에 들어가 있는 다른 차가 있을 때에는 그 차에 진로를 양보하여야 한다.”에 따라 이미 교차로에 있는 차량에게 통행 우선권이 있습니다.',1),('a4f2d8fb-7c42-11f0-a0df-bcfce7e0bced','191130_hard_1',1,'보행자가 아직 발을 내딛지 않았으므로 그냥 통과한다.','도로교통법 제27조는 보행자가 건너려고 하는 때도 보호 대상으로 포함합니다.',0),('a6584b3b-8216-11f0-afd0-d843ae853d20','left_green_right_red_basic_2',3,'교차로에서 좌회전을 하려는 차량과 해당 교차로에서 직진이나 우회전을 하려는 다른 차량이 있을 때, 좌회전 차량이 통행 우선권을 갖는다. ','도로교통법 제26조(교통정리가 없는 교차로에서의 양보운전)4항 “교통정리를 하고 있지 아니하는 교차로에서 좌회전하려고 하는 차의 운전자는 그 교차로에서 직진하거나 우회전하려는 다른 차가 있을 때에는 그 차에 진로를 양보하여야 한다.”에 따라 직진, 우회전 차량이 통행 우선권을 갖습니다.',0),('aa0cc890-8216-11f0-afd0-d843ae853d20','left_green_right_red_basic_2',4,'넓은 도로에서 교차로에 진입하려는 차량이 있을 경우, 그 차량보다 운전자(본인)의 차량이 통행 우선권을 가진다.','도로교통법 제26조(교통정리가 없는 교차로에서의 양보운전)2항 “교통정리를 하고 있지 아니하는 교차로에 들어가려고 하는 차의 운전자는 그 차가 통행하고 있는 도로의 폭보다 교차하는 도로의 폭이 넓은 경우에는 서행하여야 하며, 폭이 넓은 도로로부터 교차로에 들어가려고 하는 다른 차가 있을 때에는 그 차에 진로를 양보하여야 한다.” 에 따라 넓은 도로에서 교차로로 진입하려는 차량이 통행 우선권을 갖습니다.',0),('b5d96457-7c3a-11f0-a0df-bcfce7e0bced','87769_middle_0',1,'양 차량 모두 동시에 서행하면서 주행하여 서로 피해가도록 한다.','도로교통법 제20조 제2항 : \"좁은 도로에서 긴급자동차 외의 자동차가 서로 마주보고 진행할 때에는 다음 각 호의 구분에 따른 자동차가 도로의 우측 가장자리로 피하여 진로를 양보하여야 한다.\"\r\n두 차량이 동시에 비켜가는 것은 원칙적인 통행 방법에 위배되며, 오히려 사고 위험을 키웁니다.',0),('b927cb66-8222-11f0-afd0-d843ae853d20','87785_middle_0',1,'앞차와의 충돌을 방지하려면 우측 차선으로 이동한다.','제21조 제1항(도로교통법) – “다른 차를 앞지르려면 앞차의 좌측으로 통행하여야 한다.”\r\nA번은 우측 차선으로 이동하라는 내용이지만, 제21조 제1항은 앞 차를 앞지르려면 좌측(왼쪽) 차선으로 이동해야 한다는 규정을 두고 있습니다. 따라서 우측 차선 이동은 전진 시 앞 차와의 충돌 방지에 대한 적절한 조치가 아니며, 법적 근거와 일치하지 않습니다.',0),('b95330c7-7c3e-11f0-a0df-bcfce7e0bced','87769_middle_1',2,'양 차량이 동시에 중앙선을 넘어 피해간다.','제13조 제3항은 도로의 우측 통행을 원칙으로 하므로 중앙선 침범은 위법입니다.',0),('bb26325d-8222-11f0-afd0-d843ae853d20','87785_middle_0',2,'앞차와의 충돌을 방지하려면 좌측 차선으로 이동한다.','제21조 제1항(도로교통법) – “다른 차를 앞지르려면 앞차의 좌측으로 통행하여야 한다.”\r\nB번은 좌측 차선으로 이동을 제안하지만, 앞 차가 정지해 있는 상황에서는 앞 차를 앞지르려는 의도가 없으므로 좌측 이동이 필요 없습니다. 제19조 제1항에 따라 안전 거리 확보가 가장 중요한 조치이며, 좌측 차선 이동은 불필요하고 법적 근거가 부족합니다.',0),('bb987647-84a9-11f0-bb06-d843ae853d20','87768_middle_1',1,'좌회전하는 앞 차량을 따라 같이 좌회전한다.','도로교통법 제25조(교차로 통행방법)5항 “모든 차 또는 노면전차의 운전자는 신호기로 교통정리를 하고 있는 교차로에 들어가려는 경우에는 진행하려는 진로의 앞쪽에 있는 차 또는 노면전차의 상황에 따라 교차로(정지선이 설치되어 있는 경우에는 그 정지선을 넘은 부분을 말한다)에 정지하게 되어 다른 차 또는 노면전차의 통행에 방해가 될 우려가 있는 경우에는 그 교차로에 들어가서는 아니 된다.” 에 따르면 앞차를 따라 주행하다가 정지하게 되어 교통에 방해가 될 우려가 있다면 교차로에 들어가면 안된다고 명시하고 있습니다.',0),('bd629021-8222-11f0-afd0-d843ae853d20','87785_middle_0',3,'전진을 멈추고, 정지한 하얀색 차량과의 충돌을 피하기 위해 필요한 거리를 확보한다.','제19조 제1항(도로교통법) – “동일한 방향으로 가고 있는 앞차의 뒤를 따르는 경우에는 앞차가 갑자기 정지한 경우 그 앞차와의 충돌을 피할 수 있는 필요한 거리를 확보하여야 한다.”\r\n정지한 차량과의 충돌을 방지하기 위해서는 충분한 안전 거리를 확보해야 합니다. 이는 제19조 제1항에 명시된 바와 같이 전진 중인 차량이 앞 차를 따를 때 가장 중요한 운전 규칙입니다. 따라서 C번이 옳은 선택입니다.',1),('bfb6d7b8-8222-11f0-afd0-d843ae853d20','87785_middle_0',4,'앞차가 갑자기 정지했을 때 전진을 계속한다.','제19조 제1항(도로교통법) – “동일한 방향으로 가고 있는 앞차의 뒤를 따르는 경우에는 앞차가 갑자기 정지한 경우 그 앞차와의 충돌을 피할 수 있는 필요한 거리를 확보하여야 한다.”\r\nD번은 앞 차가 갑자기 정지했음에도 전진을 계속한다는 내용으로, 제19조 제1항에 명시된 “충돌을 피할 수 있는 필요한 거리 확보”라는 의무와 명백히 모순됩니다.',0),('bff15928-84a9-11f0-bb06-d843ae853d20','87768_middle_1',2,'교차로의 전방 신호가 초록색인 경우에는 좌회전을 진행해도 무방하다.','도로교통법 제25조(교차로 통행방법)5항 “모든 차 또는 노면전차의 운전자는 신호기로 교통정리를 하고 있는 교차로에 들어가려는 경우에는 진행하려는 진로의 앞쪽에 있는 차 또는 노면전차의 상황에 따라 교차로(정지선이 설치되어 있는 경우에는 그 정지선을 넘은 부분을 말한다)에 정지하게 되어 다른 차 또는 노면전차의 통행에 방해가 될 우려가 있는 경우에는 그 교차로에 들어가서는 아니 된다.” 에 따르면 교차로가 정체되어 있는 경우에는 신호와 상관없이 법적으로 교차로 진입을 제한하고 있습니다. ',0),('c1f52e71-7c3b-11f0-a0df-bcfce7e0bced','87769_middle_0',2,'속도가 더 빠른 차량이 우선 통행한다.','도로교통법 어디에도 속도가 빠른 차량이 우선한다는 규정은 없습니다.\r\n오히려 제20조(진로 양보의 의무)는 교행 곤란 시 일방 차량이 정지·후진하여 서로 양보할 것을 규정합니다.',0),('c268883a-84a9-11f0-bb06-d843ae853d20','87768_middle_1',3,'교차로의 전방 신호가 빨간색인 경우라도 차량이 들어갈 공간이 생기면 좌회전한다.','도로교통법 제25조(교차로 통행방법)5항 “모든 차 또는 노면전차의 운전자는 신호기로 교통정리를 하고 있는 교차로에 들어가려는 경우에는 진행하려는 진로의 앞쪽에 있는 차 또는 노면전차의 상황에 따라 교차로(정지선이 설치되어 있는 경우에는 그 정지선을 넘은 부분을 말한다)에 정지하게 되어 다른 차 또는 노면전차의 통행에 방해가 될 우려가 있는 경우에는 그 교차로에 들어가서는 아니 된다.” 에 따르면 교차로가 정체되어 있는 경우에는 교차로 진입을 제한하고 있습니다.',0),('c3a17b30-84a9-11f0-bb06-d843ae853d20','87768_middle_1',4,'교차로의 전방 신호 중 좌회전을 나타내는 신호가 초록색인 경우라도 진입하지 않는다.','도로교통법 제25조(교차로 통행방법)5항 “모든 차 또는 노면전차의 운전자는 신호기로 교통정리를 하고 있는 교차로에 들어가려는 경우에는 진행하려는 진로의 앞쪽에 있는 차 또는 노면전차의 상황에 따라 교차로(정지선이 설치되어 있는 경우에는 그 정지선을 넘은 부분을 말한다)에 정지하게 되어 다른 차 또는 노면전차의 통행에 방해가 될 우려가 있는 경우에는 그 교차로에 들어가서는 아니 된다.” 에 따르면 모든 차의 운전자는 신호등이 있는 교차로에 들어가려는 경우에는 진행하고자 하는 차로의 앞쪽에 있는 차의 상황에 따라 교차로에 정지하여야 하며 다른 차의 통행에 방해가 될 우려가 있는 경우에는 그 교차로에 들어가서는 안된다고 명시하고 있기 때문에 해당 선지가 정답입니다.',1),('c43ff181-84b3-11f0-bb06-d843ae853d20','131062_hard_1',1,'교차로에서 우회전을 하고자 하는 때에는 신호에 상관없이 정차해 주변 차량 및 보행자를 살핀다.','도로교통법 제25조(교차로 통행방법) 제1항 “모든 차의 운전자는 교차로에서 우회전을 하려는 경우에는 미리 도로의 우측 가장자리를 서행하면서 우회전하여야 한다. 이 경우 우회전하는 차의 운전자는 신호에 따라 정지하거나 진행하는 보행자 또는 자전거등에 주의하여야 한다.”에 따르면 우회전하는 차량이 반드시 정차해야 한다는 규정이 없습니다. 전방 신호가 빨간색일 때는 우선 일시정지 후 주변을 살핀 뒤 주행해야 하는 것이 옳은 주행 방법이지만, 신호와 상관없이 교차로에서 우회전하기 전 정차해야 한다는 설명은 적절하지 않습니다.',0),('c560ec65-7c42-11f0-a0df-bcfce7e0bced','191130_hard_1',2,'보행자가 도로에 내려서기 전까지는 정지할 필요가 없다.','도로교통법 제27조에 따르면 발을 내딛기 전이라도 정지해야 합니다.',0),('c6b357e5-84b3-11f0-bb06-d843ae853d20','131062_hard_1',2,'교차로에서 좌회전을 하고자 하는 때에는 항상 도로의 중앙선을 기준으로 가장 멀리 떨어진 차선으로 이동해야 한다.','도로교통법 제25조(교차로 통행방법) 제2항 “모든 차의 운전자는 교차로에서 좌회전을 하려는 경우에는 미리 도로의 중앙선을 따라 서행하면서 교차로의 중심 안쪽을 이용하여 좌회전하여야 한다. 다만, 시ㆍ도경찰청장이 교차로의 상황에 따라 특히 필요하다고 인정하여 지정한 곳에서는 교차로의 중심 바깥쪽을 통과할 수 있다.”에 따라 교차로에서 좌회전할 때는 도로의 중앙선을 따라 가장 안쪽에서 주행해야 합니다.',0),('c8ba2d5e-84b3-11f0-bb06-d843ae853d20','131062_hard_1',3,'신호기가 없는 교차로에 동시에 차량 2대가 동시에 들어가려고 할 때는 좌측도로 즉, 더 왼쪽에 위치한 차량에게 진로를 양보해야 한다.','도로교통법 제26조(교통정리가 없는 교차로에서의 양보운전) 제3항 “교통정리를 하고 있지 아니하는 교차로에 동시에 들어가려고 하는 차의 운전자는 우측도로의 차에 진로를 양보하여야 한다.”에 따르면 교통정리가 없는 교차로에 차량이 동시에 진입하려고 하면 우측도로의 차량이 우선권을 갖습니다.',0),('c9f94068-84b3-11f0-bb06-d843ae853d20','131062_hard_1',4,'교차로에서 우회전을 하고자 하는 때에는 도로의 우측 가장자리를 서행하면서 우회전하여야 한다.','도로교통법 제25조(교차로 통행방법) 제1항 “모든 차의 운전자는 교차로에서 우회전을 하려는 경우에는 미리 도로의 우측 가장자리를 서행하면서 우회전하여야 한다. 이 경우 우회전하는 차의 운전자는 신호에 따라 정지하거나 진행하는 보행자 또는 자전거등에 주의하여야 한다.”에 부합하는 설명이기 때문에 해당 선지가 정답입니다.',1),('cc040604-7c42-11f0-a0df-bcfce7e0bced','191130_hard_1',3,'횡단보도 앞에서 일시정지하여 보행자가 먼저 건너도록 해야 한다.','도로교통법 제27조 7항 : \"모든 차 또는 노면전차의 운전자는 제12조제1항에 따른 어린이 보호구역 내에 설치된 횡단보도 중 신호기가 설치되지 아니한 횡단보도 앞(정지선이 설치된 경우에는 그 정지선을 말한다)에서는 보행자의 횡단 여부와 관계없이 일시정지하여야 한다\" 에 따라 반드시 정지해야 합니다.',1),('cf38c05f-7c3d-11f0-a0df-bcfce7e0bced','87769_middle_0',3,'둘 중 한 차량이 일시 정지하거나 후진하여 서로 통행할 수 있도록 양보한다.','도로교통법 제20조 제2항: “좁은 도로에서 긴급자동차 외의 자동차가 서로 마주보고 진행할 때에는 다음 각 호의 구분에 따른 자동차가 도로의 우측 가장자리로 피하여 진로를 양보하여야 한다.\r\n\r\n1. 비탈진 좁은 도로에서 자동차가 서로 마주보고 진행하는 경우에는 올라가는 자동차\r\n2. 비탈진 좁은 도로 외의 좁은 도로에서 사람을 태웠거나 물건을 실은 자동차와 동승자(同乘者)가 없고 물건을 싣지 아니한 자동차가 서로 마주보고 진행하는 경우에는 동승자가 없고 물건을 싣지 아니한 자동차”\r\n\r\n따라서 운전자 차량이 멈추고, 맞은편 차량이 후진하여 비켜주는 상황은 법 규정에 맞는 올바른 대처입니다.',1),('d26f11ad-7c42-11f0-a0df-bcfce7e0bced','191130_hard_1',4,'보행자가 서 있는 경우 속도를 줄이면 된다.','단순히 서행만으로는 의무를 다한 것이 아닙니다. 보행자 보호 의무(도로교통법 제27조 7항)에 따라 반드시 정지해야 합니다.',0),('d43b3700-7c3e-11f0-a0df-bcfce7e0bced','87769_middle_1',3,'한 쪽 차량이 정지하거나 후진하여 서로 통행할 수 있도록 협력한다.','제20조 제2항: “좁은 도로에서 긴급자동차 외의 자동차가 서로 마주보고 진행할 때에는 다음 각 호의 구분에 따른 자동차가 도로의 우측 가장자리로 피하여 진로를 양보하여야 한다.” 에 따라 정지한 후 후진하여 서로 통행이 가능하도록 양보한다.',1),('d69a8bea-84aa-11f0-bb06-d843ae853d20','87768_middle_2',1,'신호가 초록색이므로, 정체 상태라도 서행하면서 횡단보도를 넘어 진입한다.','- 도로교통법 제27조 제1항\r\n    \r\n    \"모든 차 또는 노면전차의 운전자는 보행자(제13조의2제6항에 따라 자전거등에서 내려서 자전거등을 끌거나 들고 통행하는 자전거등의 운전자를 포함한다)가 횡단보도를 통행하고 있거나 통행하려고 하는 때에는 보행자의 횡단을 방해하거나 위험을 주지 아니하도록 그 횡단보도 앞(정지선이 설치되어 있는 곳에서는 그 정지선을 말한다)에서 일시정지하여야 한다.\"\r\n    \r\n    신호가 녹색이더라도 보행자 유무와 상관없이 **횡단보도 위에서 정차하거나 통행을 방해할 가능성**이 있다면 횡단보도 진입을 하지 않는 것을 권고합니다.\r\n    \r\n    따라서 서행하면서라도 진입하는 것은 옳지 않은 행동입니다.',0),('d8df1d4f-84aa-11f0-bb06-d843ae853d20','87768_middle_2',2,'보행자가 없을 때는 횡단보도 위에 정차해도 무방하다.','- 도로교통법 제27조 제1항\r\n    \r\n    \"모든 차 또는 노면전차의 운전자는 보행자(제13조의2제6항에 따라 자전거등에서 내려서 자전거등을 끌거나 들고 통행하는 자전거등의 운전자를 포함한다)가 횡단보도를 통행하고 있거나 통행하려고 하는 때에는 보행자의 횡단을 방해하거나 위험을 주지 아니하도록 그 횡단보도 앞(정지선이 설치되어 있는 곳에서는 그 정지선을 말한다)에서 일시정지하여야 한다.\"\r\n    \r\n    횡단보도는 **보행자 통행권을 보호하기 위한 구간**으로, 보행자가 없어도 점유하거나 정차하는 것은 잘못된 행동입니다.\r\n    \r\n    따라서 \"보행자가 없으면 괜찮다\"는 판단은 잘못됐습니다.',0),('db2d8235-8496-11f0-bb06-d843ae853d20','110371_basic_1',1,'다른 차량를 앞지르려면 앞차의 왼쪽 차로로 차량을 회피해 통행하여야 한다.','도로교통법 제21조(앞지르기 방법 등) 1항 “모든 차의 운전자는 다른 차를 앞지르려면 앞차의 좌측으로 통행하여야 한다.”에 따르면 다른 차량을 앞지르기 위해서 전방 차량의 왼쪽으로 주행해야 합니다.',0),('dc9fe79b-84aa-11f0-bb06-d843ae853d20','87768_middle_2',3,'정체 상황에서는 횡단보도를 침범하지 않도록 그 앞에서 정지해야 한다.','도로교통법 제27조 제1항에 따르면 횡단보도 위에서 정차 자체가 보행자 횡단 방해로 간주되며, \r\n\r\n도로교통법 시행규칙 별표2에 따르면 황색, 적색의 등화에서 “차마는 정지선이 있거나 횡단보도가 있을 때에는 그 직전이나 교차로의 직전에 정지하여야 하며, 이미 교차로에 차마의 일부라도 진입한 경우에는 신속히 교차로 밖으로 진행하여야 한다.” 에 따라 신호가 언제 바귈지 모르기 때문에 **정지선 앞에서 정차하는 것이 법적·안전적으로 정답입니다.**',1),('dcaeba23-8226-11f0-afd0-d843ae853d20','192029_hard_2',1,'정차','도로교통법 제32조(정차 및 주차의 금지)에 따르면 교차로에서 정차를 금지하고 있습니다.',1),('ddebe814-84aa-11f0-bb06-d843ae853d20','87768_middle_2',4,'신호가 곧 바뀔 수 있으므로, 정지선이 아닌 횡단보도 중앙에서 대기하는 것이 안전하다.','도로교통법 제32조 제2항 “모든 차의 운전자는 다음 각 호의 어느 하나에 해당하는 곳에서는 차를 정차하거나 주차하여서는 아니 된다. - 교차로ㆍ횡단보도ㆍ건널목이나 보도와 차도가 구분된 도로의 보도” 에 따라 횡단보도 위에 정차하는 행위를 금하고 있습니다. \r\n\r\n또한 도로교통법 제27조 제1항 \"모든 차 또는 노면전차의 운전자는 보행자(제13조의2제6항에 따라 자전거등에서 내려서 자전거등을 끌거나 들고 통행하는 자전거등의 운전자를 포함한다)가 횡단보도를 통행하고 있거나 통행하려고 하는 때에는 보행자의 횡단을 방해하거나 위험을 주지 아니하도록 그 횡단보도 앞(정지선이 설치되어 있는 곳에서는 그 정지선을 말한다)에서 일시정지하여야 한다.\" 에 따라 횡단보도 중앙이 아니라 횡단보도 전에 정지하는 것을 권고합니다.',0),('de988d46-8226-11f0-afd0-d843ae853d20','192029_hard_2',2,'서행','회전교차로에서 서행을 금지하는 법이나 지침은 존재하지 않습니다.',0),('dec85173-8496-11f0-bb06-d843ae853d20','110371_basic_1',2,'도로의 중앙선이 황색 점선인 경우 반대방향으로 주행하는 차량이 없을 때, 중앙선을 넘어 차로를 변경해 앞지르기가 가능하다.','도로교통법 시행규칙 별표 6 “황색점선은 반대방향의 교통에 주의하면서 일시적으로 반대편 차로로 넘어갈 수 있으나 진행방향 차로로 다시 돌아와야 함을 표시하는 것”에 따르면 반대방향의 차량이 없을 경우 일시적으로 반대편 차로로 넘어가 주행 가능합니다.',0),('e049a03c-8226-11f0-afd0-d843ae853d20','192029_hard_2',3,'앞지르기','도로교통법 제22조(앞지르기 금지의 시기 및 장소)에 따르면 교차로 안에서의 앞지르기를 금지하고 있습니다.',1),('e1e57a17-8226-11f0-afd0-d843ae853d20','192029_hard_2',4,'일시정지','도로교통법 제32조(정차 및 주차의 금지)에 따르면 교차로에서 위험방지를 위하여 일시 정지를 하는 것은 허용되고 있습니다.',0),('e248a2bb-8496-11f0-bb06-d843ae853d20','110371_basic_1',3,'중앙선이 황색 실선이면서 단선인 경우(황색 실선 한 줄만 있는 경우) 앞지르기가 불가능하다.','도로교통법 시행규칙 별표 6 “황색실선은 차마가 넘어갈 수 없음을 표시하는 것”에 따르면 중앙선이 황색 실선일 경우는 단선, 복선과 상관없이 앞지르기가 불가능합니다.',0),('e3067436-84b2-11f0-bb06-d843ae853d20','149112_hard_2',1,'우회전을 하려는 차는 중앙선을 따라 서행하면서 회전해야 한다.','도로교통법 제25조 제1항은 우회전 시 \"도로의 우측 가장자리를 서행하면서 우회전하여야 한다\"라고 규정하며, 중앙선에 붙어 서행해야 한다는 내용은 완전히 상반된 위반 규정입니다.',0),('e3ac0d6e-8496-11f0-bb06-d843ae853d20','110371_basic_1',4,'편도 2차로 고속도로에서 1차로는 앞지르기를 하려는 경형·소형·중형 승용차만이 통행 가능하다.','도로교통법 시행규칙 별표 9 “편도 2차로 고속도로 - 1차로로 통행할 수 있는 차종 : 앞지르기를 하려는 모든 자동차. 다만, 차량통행량 증가 등 도로상황으로 인하여 부득이하게 시속 80킬로미터 미만으로 통행할 수밖에 없는 경우에는 앞지르기를 하는 경우가 아니라도 통행할 수 있다.” 에 따르면 앞지르기를 하려는 모든 자동차가 1차로로 통행 가능하기 때문에 경형·소형·중형 승용차만이 통행 가능하다는 것은 잘못된 설명이다.',1),('e4f463f2-849d-11f0-bb06-d843ae853d20','110369_middle_2',1,'공사구간에서는 추월이 불가능하다.','도로교통법 제22조(앞지르기 금지의 시기 및 장소) 제3항 “모든 차의 운전자는 다음 각 호의 어느 하나에 해당하는 곳에서는 다른 차를 앞지르지 못한다. - (중략) 시ㆍ도경찰청장이 도로에서의 위험을 방지하고 교통의 안전과 원활한 소통을 확보하기 위하여 필요하다고 인정하는 곳으로서 안전표지로 지정한 곳 (중략) ”에 따라 안전표시로 지정된 공사구역에서는 사고 위험이 높기 때문에 다른 차량을 추월하는 게 금지되어 있습니다.',0),('e520d761-84b2-11f0-bb06-d843ae853d20','149112_hard_2',2,'좌회전을 하려는 차는 도로의 우측 가장자리를 따라 서행하며 교차로를 돌아야 한다.','도로교통법 제25조 제2항은 좌회전 시에는 \"도로의 중앙선을 따라 서행하면서 교차로의 중심 안쪽을 이용하여 좌회전하여야 한다\"라고 명시합니다. 우측 가장자리를 사용하는 것은 자전거등에만 적용되는 예외 규정입니다.',0),('e5dc39ce-7c3e-11f0-a0df-bcfce7e0bced','87769_middle_1',4,'먼저 도착한 차량이 우선적으로 통행한다.','법 조항에 “먼저 도착한 차량 우선” 규정은 없습니다.',0),('e70b18f2-849d-11f0-bb06-d843ae853d20','110369_middle_2',2,'오른쪽 차로의 공사구간 진입 시, 반대 차로에 차량이 없을 때만 일시적으로 왼쪽 차로로 통행이 가능하다.','도로교통법 제13조(차마의 통행) 제4항 “차마의 운전자는 제3항에도 불구하고 다음 각 호의 어느 하나에 해당하는 경우에는 도로의 중앙이나 좌측 부분을 통행할 수 있다. - (중략) 도로의 파손, 도로공사나 그 밖의 장애 등으로 도로의 우측 부분을 통행할 수 없는 경우 (중략)” 에 따라 공사 구역 때문에 오른쪽 차로로 통행할 수 없는 경우에는 도로의 왼쪽 차로를 통행할 수 있습니다.',0),('e72f6e0b-8215-11f0-afd0-d843ae853d20','left_green_right_red_basic_0',1,'운전자 차량이 좌회전 차로에 있고, 신호에 따라 좌회전했으므로 신호위반이 아니다.','도로교통법 제25조 제2항 “ 모든 차의 운전자는 교차로에서 좌회전을 하려는 경우에는 미리 도로의 중앙선을 따라 서행하면서 교차로의 중심 안쪽을 이용하여 좌회전하여야 한다.”에 따른 주행 방법이므로 정답입니다.',1),('e7de04d2-84b2-11f0-bb06-d843ae853d20','149112_hard_2',3,'우회전하려는 차는 정지선, 횡단보도, 교차로 직전에서 반드시 정지한 후, 다른 차량의 통행을 방해하지 않으며 우회전할 수 있다.','도로교통법 시행규칙 개정 규정은, 우회전 시 \"정지선, 횡단보도 및 교차로의 직전에서 정지한 후 … 우회전할 수 있다\"라고 명확히 규정합니다. 본 규정은 특히 적색 신호 시에도 무조건 일시정지 후 우회전 가능함을 강조하며, 보행자와의 충돌 위험을 최소화하도록 설계 되었습니다.',1),('e91e970e-84b2-11f0-bb06-d843ae853d20','149112_hard_2',4,'좌회전 시 반드시 교차로 중심의 바깥쪽으로 통과해야 한다.','도로교통법 제25조 제2항은 좌회전 시 교차로 중심 안쪽을 이용하도록 규정하며, 중심 바깥쪽 통과는 예외적으로 지방경찰처장이 지정한 경우에만 허용됩니다. 따라서 \"반드시 바깥쪽\"은 정반대의 위반 규정입니다.',0),('e9a33d44-849d-11f0-bb06-d843ae853d20','110369_middle_2',3,'도로공사의 유형 중 이동 공사는 시속 5km 이하의 속도로 이동하면서 수행하는 공사를 뜻합니다.','도로 공사장 교통관리지침에 따르면 도로 공사에는 고정 공사와 이동 공사 등 다양한 유형의 공사가 진행됩니다. 고정 공사는 공사 지점이 공사가 끝날 때까지 이동하지 않는 공사 또는 이동하더라도 하루를 넘기고 이동하는 공사를 말하는데, 대부분의 중장기 공사와 고정 단기공사가 여기에 해당됩니다. 이동 공사는 시속 5㎞/시 이하의 이동 속도로 이동하면서 수행하는 공사를 말합니다.',0),('eb012780-849d-11f0-bb06-d843ae853d20','110369_middle_2',4,'고속도로에서 공사구간을 마주치는 경우, 제한속도는 시속 50킬로미터로 제한되어 있다.','공사구간의 경우 구간별로 시속 80킬로미터와 시속 60킬로미터로 제한되어 있어 속도제한표지를 인지하고 충분히  감속하여 운행하여야 합니다.(국토부 도로공사장 교통관리지침, 교통고속도로 공사장 교통관리기준)',1),('eb611f5d-8215-11f0-afd0-d843ae853d20','left_green_right_red_basic_0',2,'직진 신호가 빨간색이므로 운전자의 주행은 신호위반에 해당한다.','도로교통법 제25조 제2항에 따라 좌회전 차로에서 신호에 맞춰 주행하였다면 신호위반이 아니므로 오답입니다.',0),('ec29ff6d-8221-11f0-afd0-d843ae853d20','110369_middle_0',1,'라바콘(주황색 꼬깔콘)을 피해 차로를 변경할 때, 비상 점멸등을 켜야 한다.','도로교통법 제 13조 4항 “차마의 운전자는 제3항에도 불구하고 다음 각 호의 어느 하나에 해당하는 경우에는 도로의 중앙이나 좌측 부분을 통행할 수 있다. - 도로의 파손, 도로공사나 그 밖의 장애 등으로 도로의 우측 부분을 통행할 수 없는 경우”에 해당하므로 좌측통행이 허용되지만 비상 점멸등을 키는 것을 권고합니다.',1),('ed5f265a-8216-11f0-afd0-d843ae853d20','left_green_right_red_basic_3',1,'신호기가 초록색 직진 신호라도 맞은편에서 직진 차량이 없으면 좌회전할 수 있다.','- 도로교통법 제26조 (교통정리가 없는 교차로에서의 양보운전) 제4항 “교통정리를 하고 있지 아니하는 교차로에서 좌회전하려고 하는 차의 운전자는 그 교차로에서 직진하거나 우회전하려는 다른 차가 있을 때에는 그 차에 진로를 양보하여야 한다.”에 따라 직진 차량이 없을 때는 좌회전이 가능하며, 이 상황이 정답입니다.\r\n    \r\n비보호 좌회전이 허용된 교차로에서는 신호에 관계없이 **직진·우회전 차량의 진행을 방해하지 않는 한도 내에서 좌회전 가능**합니다.',1),('eff24adf-8215-11f0-afd0-d843ae853d20','left_green_right_red_basic_0',3,'좌회전 신호가 초록색이므로 모든 차량이 방향에 상관없이 주행 가능하다.','좌회전 신호는 좌회전 차로 차량에게만 적용. 모든 차량이 진행 가능한 것이 아니므로 오답입니다.',0),('f16a8aea-8216-11f0-afd0-d843ae853d20','left_green_right_red_basic_3',2,'직진 차량이 이미 교차로에 진입 중이어도 서둘러 좌회전을 하면 된다.','- 도로교통법 제26조 (교통정리가 없는 교차로에서의 양보운전) 제4항 “교통정리를 하고 있지 아니하는 교차로에서 좌회전하려고 하는 차의 운전자는 그 교차로에서 직진하거나 우회전하려는 다른 차가 있을 때에는 그 차에 진로를 양보하여야 한다.”에 따르면 직진 차량은 교차로 통행 우선권을 가집니다. 이미 진입한 직진 차량을 방해하면 사고 책임은 좌회전 차량에 있습니다.\r\n    \r\n따라서 직진 차량이 진입했을 때는 좌회전할 수 없습니다.',0),('f304e6cd-8215-11f0-afd0-d843ae853d20','left_green_right_red_basic_0',4,'직진 차로에서 출발했더라도 좌회전으로 방향을 바꿨기 때문에 신호위반이 아니다.','차로 선택과 무관하게 “신호등 지시를 따라야 함”(제5조). 직진 신호가 빨간색이므로 직진 차로에서 출발하면 신호를 위반하는 것이기 때문에 오답입니다.',0),('f334ee05-8221-11f0-afd0-d843ae853d20','110369_middle_0',2,'맞은편 차량을 발견했을 때, 속도를 줄이면서 중앙선에서 주행한다.','“도로교통법 제13조 제3항”에 명시된 “차마의 운전자는 도로(보도와 차도가 구분된 도로에서는 차도를 말한다)의 중앙(중앙선이 설치되어 있는 경우에는 그 중앙선을 말한다. 이하 같다) 우측 부분을 통행하여야 한다.”(즉, 우측 차선 사용이 허용됨)를 근거로, 반대 차로에서 차량이 오는 상황에서는 우측 차선으로 돌아가서 차간격을 확보하고 안전을 확보해야 함을 의미합니다.',0),('f3d09a2d-7c3f-11f0-a0df-bcfce7e0bced','87769_middle_2',1,'속도를 올려 먼저 통과한다.','속도를 올리면 사고 위험이 커지며 도로교통법 제1조(안전 확보의 기본 원칙)에 반합니다.',0),('f5f8fff3-8216-11f0-afd0-d843ae853d20','left_green_right_red_basic_3',3,'좌회전 신호가 없으므로 반드시 직진 신호가 끝날 때까지 기다려야 한다.','도로교통법 시행규칙 [별표 6]에 따르면 “비보호 표시 - 진행신호에 반대방면에서 오는 교통에 방해가 되지 않게 좌회전을 조심스럽게 할 수 있다는 표시” 이므로 교통에 방해가 되지 않는다면 직진 신호가 끝날 때까지 기다리지 않고 좌회전이 가능합니다.',0),('f6e0a91c-7c43-11f0-a0df-bcfce7e0bced','zigzag_basic_0',1,'차량을 좌우로 흔들며 주행하라는 의미이다.','한국도로교통공단의 “교통안전시설(노면표시) 설치·관리 업무편람”에 따르면 지그재그 노면표시는 보행자 보호 및 서행 의무를 강조하는 표시이므로 해당 선지는 오답입니다.',0),('f78dfd3d-8221-11f0-afd0-d843ae853d20','110369_middle_0',3,'전조등을 켜 접근하는 맞은편 차량에게 정지할 것을 요청한다.','도로교통법 제37조(차와 노면전차의 등화) : ”모든 차 또는 노면전차의 운전자는 다음 각 호의 어느 하나에 해당하는 경우에는 대통령령으로 정하는 바에 따라 전조등(前照燈), 차폭등(車幅燈), 미등(尾燈)과 그 밖의 등화를 켜야 한다.”에서 영상 속 상황이 해당 상황에 포함되지 않으므로 오답입니다.',0),('f8fb34a9-8216-11f0-afd0-d843ae853d20','left_green_right_red_basic_3',4,'횡단보도 보행자 신호가 빨간색이면, 보행자가 없다고 가정하고 바로 좌회전할 수 있다.','도로교통법 제27조 보행자의 보호에 따르면 모든 차량은 보행자의 통행을 방해하면 안됩니다. 보행자 신호가 빨간색이더라도 횡단보도에 보행자가 진입할 가능성이 있으므로 반드시 확인해야 하며, 보행자가 없다고 가정하고 바로 좌회전하는 것은 위험합니다.',0),('f99a4644-8221-11f0-afd0-d843ae853d20','110369_middle_0',4,'라바콘(주황색 꼬깔콘)을 피해 차로를 변경할 때, 방향 지시등을 켜 주변 차량에게 차로 변경을 알린다.','방향 지시등이 아닌 비상 점멸등을 켜야하기 때문에 오답입니다.',0),('fd0d7245-7c43-11f0-a0df-bcfce7e0bced','zigzag_basic_0',2,'차량의 속도를 줄이고 보행자 안전을 확보하라는 의미이다.','지그재그 노면표시는 서행 안전표지는 “교통안전시설(노면표시) 설치·관리 업무편람”에 따라 서행의 의미이며, 도로교통법 제31조(서행 또는 일시정지할 장소)1항 “모든 차 또는 노면전차의 운전자는 다음 각 호의 어느 하나에 해당하는 곳에서는 서행하여야 한다. - 시ㆍ도경찰청장이 도로에서의 위험을 방지하고 교통의 안전과 원활한 소통을 확보하기 위하여 필요하다고 인정하여 안전표지로 지정한 곳”에 따라 법적 효력을 가집니다.',1);
/*!40000 ALTER TABLE `options` ENABLE KEYS */;
UNLOCK TABLES;
