DROP TABLE IF EXISTS `quiz`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `quiz` (
  `quiz_id` varchar(36) NOT NULL COMMENT 'PK. 퀴즈 고유번호',
  `video_id` varchar(36) DEFAULT NULL COMMENT 'FK → video.video_id',
  `question_text` text COMMENT '문제 본문',
  `category_sub_name_1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `category_sub_name_2` varchar(50) DEFAULT NULL,
  `category_sub_name_3` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`quiz_id`),
  KEY `video_id_idx` (`video_id`),
  KEY `fk_quiz_category_sub_name_1` (`category_sub_name_1`),
  KEY `fk_quiz_category_sub_name_2` (`category_sub_name_2`),
  KEY `fk_quiz_category_sub_name_3` (`category_sub_name_3`),
  CONSTRAINT `fk_quiz_category_sub_name_1` FOREIGN KEY (`category_sub_name_1`) REFERENCES `category` (`category_sub_name`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_quiz_category_sub_name_2` FOREIGN KEY (`category_sub_name_2`) REFERENCES `category` (`category_sub_name`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_quiz_category_sub_name_3` FOREIGN KEY (`category_sub_name_3`) REFERENCES `category` (`category_sub_name`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_quiz_video` FOREIGN KEY (`video_id`) REFERENCES `video` (`video_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='퀴즈(문제) : 영상, 문제 본문, 상황 유형';
