INSERT INTO `quiz` VALUES ('110353_middle_0','middle_110353','다음은 한 운전자가 주행 중 경험한 실제 도로 상황이다. 다음 중 도로교통법상 명백한 위반에 해당하는 행동은 무엇인가?','공사 구역','도로 신호',NULL),('110353_middle_1','middle_110353','다음 중 공사 구간을 통행하는 운전자의 행위 중 도로교통법상 위법에 해당하는 것은 무엇인가?','공사 구역',NULL,NULL),('110353_middle_2','middle_110353','다음 중 도로교통법상 어린이 보호구역 내에서 올바른 주행 방법에 해당하는 것을 모두 고르시오.','어린이 보호 구역',NULL,NULL),('110353_middle_3','middle_110353','다음 중 적색으로 포장된 아스팔트 구간이 아닌 것은?','어린이 보호 구역',NULL,NULL),('110369_middle_0','middle_110369','영상을 보았을 때, 다음 중 올바른 조치로 옳은 것은?','공사 구역',NULL,NULL),('110369_middle_1','middle_110369','다음 중 도로교통법 상 차로변경에 대한 설명으로 맞는 것은? ','차로 변경',NULL,NULL),('110369_middle_2','middle_110369','다음 중 도로 위의 공사안내 표지판 등으로 표시된 공사구간에 관한 설명으로 틀린 것은?  ','공사 구역',NULL,NULL),('110371_basic_0','basic_110371','전방에 하얀색 화물차가 주차되어 있어 차로가 막혀 있는 상황에서 운전자 차량의 가장 옳은 주행 방법은 무엇인가?','차로 변경','양보 운전',NULL),('110371_basic_1','basic_110371','도로교통법령상 다른 차량을 앞지르기하는 법에 대한 설명으로 옳지 않은 것은?','차로 변경',NULL,NULL),('131062_hard_0','hard_131062','교차로에서 운전자 차량이 직진을 하고 있다. \r\n교차로 전방 신호는 적색 점멸 신호(빨간불이 깜빡임)이다. \r\n교차로 한가운데에서 운전자 차량과 검은색 차량이 부딪히는 사고가 발생한다. \r\n해당 상황에서 사고를 피하려면 운전자가 어떤 행동을 했어야 하는가?','교차로','도로 신호',NULL),('131062_hard_1','hard_131062','교차로에서 주행하는 방법을 가장 바르게 설명한 것은?','교차로',NULL,NULL),('131062_hard_2','hard_131062','다음 중 신호의 뜻으로 옳은 것은?','도로 신호',NULL,NULL),('149112_hard_0','hard_149112','교차로의 전방 신호가 빨간색이고, 운전자 차량이 교차로에서 우회전 중 검은색 세단과 충돌한 경우, 충돌 방지 책임을 지는 운전자를 올바르게 기술한 것은?','교차로','도로 신호',NULL),('149112_hard_1','hard_149112','도로교통법령상 신호의 뜻에 대한 설명으로 맞는 2가지는?','도로 신호',NULL,NULL),('149112_hard_2','hard_149112','다음 중 교차로에서의 우회전 또는 좌회전에 관한 설명으로 도로교통법 및 시행규칙에 가장 부합하는 것은 무엇인가?','교차로',NULL,NULL),('154060_basic_0','basic_154060','다음 상황에서 운전자는 어떤 조치를 취해야 하는가?','차로 변경','차의 신호',NULL),('154060_basic_1','basic_154060','다음 중 앞지르기가 가능한 장소는?','차로 변경',NULL,NULL),('154060_basic_2','basic_154060','다음 중 터널을 통과할 때 안전을 위해 운전자가 하는 행동으로 옳은 것은?','차의 신호','차로 변경',NULL),('191130_hard_0','hard_191130','영상에서 운전자 차량이 횡단보도를 건너는 보행자와 충돌했다.\r\n이 상황에 대한 올바른 법적 해석은 무엇인가?','보행자 보호',NULL,NULL),('191130_hard_1','hard_191130','운전자가 신호등 없는 횡단보도에 접근했을 때, 보행자가 길을 건너려고 기다리고 있다면 운전자는 어떻게 해야 하는가?','보행자 보호',NULL,NULL),('191130_hard_2','hard_191130','운전자가 우회전할 때 횡단보도에 보행자가 통행 중인 경우, 운전자의 옳은 조치는?','보행자 보호',NULL,NULL),('192029_hard_0','hard_192029','해당 영상은 회전교차로 내의 차대차 충돌영상이다. 영상에 대한 설명으로 옳은 것은?','교차로','차의 신호',NULL),('192029_hard_1','hard_192029','회전교차로에서의 통행 방법으로 가장 옳은 것은?','교차로','차의 신호',NULL),('192029_hard_2','hard_192029','다음 중 회전교차로에서의 금지 행위인 것을 모두 고르시오.','교차로',NULL,NULL),('192029_hard_3','hard_192029','다음 중 회전교차로에서 통행 우선권이 보장된 회전차량은?','교차로','차의 신호',NULL),('87768_middle_0','middle_87768','다음 영상과 같이 “전방 정체가 생겼을 때” 운전자 차량이 정지할 수 있는 행위에 대한 설명으로 가장 적절한 것은?','주차 및 정차',NULL,NULL),('87768_middle_1','middle_87768','앞의 차량들로 인해 정체된 교차로에서 좌회전할 경우 가장 옳은 방법은?','교차로','도로 신호',NULL),('87768_middle_2','middle_87768','일반도로에서 신호등이 초록색으로 바뀌어 출발하려던 운전자가 전방 차량 정체로 인해 진행하면 횡단보도 위에서 정지할 우려가 있는 상황이다. 이 경우 운전자가 취해야 할 올바른 행동은 무엇인가?','노면 표시','보행자 보호',NULL),('87769_middle_0','middle_87769','영상에서 주행 방향이 정해지지 않은 좁은 골목길에서 운전자 차량과 맞은편 차량이 마주쳤다.\n이때 운전자가 취해야 할 올바른 조치는 무엇인가?','양보 운전',NULL,NULL),('87769_middle_1','middle_87769','좁은 골목길에서 대형 버스와 승용차가 마주쳤다. 이때 서로 비켜가게 주행하는 것이 곤란하다면 어떻게 해야 하는가?','양보 운전',NULL,NULL),('87769_middle_2','middle_87769','좁은 도로에서 마주 오는 차량과 서로 비켜가게 주행하는 것이 불가능한 경우, 운전자가 가장 먼저 해야 할 올바른 행동은 무엇인가? (마주 오는 차량은 동승자가 있고 운전자 차량은 동승자가 없는 상태이다.)','양보 운전',NULL,NULL),('87785_middle_0','middle_87785','영상과 같이 전진 중인 운전자 차량 앞에 정지해 있는 하얀색 차량이 있을 때, 운전자는 무엇을 해야 하는가?','차로 변경',NULL,NULL),('87785_middle_1','middle_87785','도로교통법령상 차로에 따른 통행차의 기준에 대한 설명이다. 잘못된 것은?','차선 규칙',NULL,NULL),('87785_middle_2','middle_87785','도로교통법령상 차로에 따른 통행구분 설명이다. 잘못된 것은?','차선 규칙',NULL,NULL),('98453_basic_0','basic_98453','해당 영상에서 운전자 차량이 회전교차로에 진입할 때 가장 적절한 운전 행위는?','교차로',NULL,NULL),('98453_basic_1','basic_98453','다음 중 회전교차로를 통행 중인 운전자의 행동으로 적절한 것을 모두 고르시오.','교차로','차의 신호',NULL),('98453_basic_2','basic_98453','회전교차로 안에서 2차로로 주행 중이던 차량이 차선을 변경하려고 한다. 이때 올바른 방법은?','교차로','차로 변경','차의 신호'),('busstop_hard_0','hard_busstop','영상과 같이 운전자 차량이 보행자와 충돌한 경우, 도로교통법상 위반에 해당하는 것은 무엇인가?','노면 표시','보행자 보호',NULL),('busstop_hard_1','hard_busstop','중앙 버스전용차로에 대한 설명으로 올바른 것은?','노면 표시',NULL,NULL),('busstop_hard_2','hard_busstop','중앙 버스전용차로에 대한 설명으로 올바른 것은?','노면 표시',NULL,NULL),('busstop_hard_3','hard_busstop','도로교통법령상 고속도로의 버스전용차로를 통행할 수 있는 차량은 무엇인가?','노면 표시',NULL,NULL),('left_green_right_red_basic_0','basic_left_green_right_red','영상에서의 운전자 차량의 주행에 대한 도로교통법상 옳은 판단은 무엇인가?','도로 신호',NULL,NULL),('left_green_right_red_basic_1','basic_left_green_right_red','교차로에서 좌회전할 때 발생할 수 있는 가장 위험한 요인 및 상황은 무엇인가?','교차로',NULL,NULL),('left_green_right_red_basic_2','basic_left_green_right_red','신호등이 없는 교차로에서의 옳은 것은?','교차로',NULL,NULL),('left_green_right_red_basic_3','basic_left_green_right_red','비보호 좌회전 교차로에서 운전자가 좌회전을 하려는 상황이다. 다음 중 가장 올바른 운전 방법은 무엇인가?','교차로','도로 신호',NULL),('zigzag_basic_0','basic_zigzag','이 영상에서 도로의 “지그재그” 노면표시는 무엇을 의미하는가?','노면 표시',NULL,NULL),('zigzag_basic_1','basic_zigzag','다음 중 노면표시에 대한 설명으로 옳은 것은 무엇인가?','노면 표시',NULL,NULL),('zigzag_basic_2','basic_zigzag','다음 설명 중 옳은 것을 모두 고르시오.','노면 표시','차의 신호',NULL),('zigzag_basic_3','basic_zigzag','도로의 구간 또는 장소에 설치하는 노면표시에 대한 설명으로 맞는 것은?','노면 표시',NULL,NULL);
