/*!50001 CREATE VIEW `v_history_detailed` AS SELECT 
 1 AS `history_id`,
 1 AS `user_name`,
 1 AS `quiz_set_no`,
 1 AS `quiz_set_date`,
 1 AS `quiz_id`,
 1 AS `video_id`,
 1 AS `question_text`,
 1 AS `category_sub_name_1`,
 1 AS `category_sub_name_2`,
 1 AS `category_sub_name_3`,
 1 AS `option_label`,
