CREATE TABLE `video` (
  `video_id` varchar(36) NOT NULL COMMENT 'PK. 영상 고유번호',
  `video_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '영상 URL',
  `difficulty` tinyint unsigned NOT NULL COMMENT '난이도 (상:1, 중:2, 하:3)',
  `description` text COMMENT '도로 주행 상황 설명 텍스트',
  PRIMARY KEY (`video_id`),
  CONSTRAINT `chk_video_difficulty` CHECK ((`difficulty` between 1 and 3))
